insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('parent-routine-builder', 'Parent Routine Builder', 'worksheet'::resource_kind, 'A page for building morning and bedtime routines with the child''s input.', 'Use it to help a parent set up predictable routines the child helps shape.', array['Adults']::text[], '30 minutes', 'Walk through the morning and bedtime with the parent. List steps, then ask the child to add ideas. Use visual charts for young children. Start with one routine and expand later. Keep tone warm, not rigid.', '[{"id": "f0", "type": "textarea", "label": "Our morning steps"}, {"id": "f1", "type": "textarea", "label": "Our bedtime steps"}, {"id": "f2", "type": "textarea", "label": "What my child wants to add"}, {"id": "f3", "type": "textarea", "label": "Where we get stuck"}, {"id": "f4", "type": "textarea", "label": "A visual cue I will use"}, {"id": "f5", "type": "textarea", "label": "How I will praise effort"}]'::jsonb, array['parenting', 'routines', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('praise-jar-family-craft', 'Praise Jar Family Craft', 'kids'::resource_kind, 'A jar the family fills with notes of things that went well.', 'Use it to help a family notice and name effort.', array['Children']::text[], '25 minutes', 'The child decorates a jar and the parent writes or draws notes of effort. Read a few notes at dinner or bedtime. Tell the parent to praise specific actions. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw our jar"}, {"id": "f1", "type": "textarea", "label": "A note about something I did well"}, {"id": "f2", "type": "textarea", "label": "A note about my grown-up"}, {"id": "f3", "type": "textarea", "label": "How I felt reading notes"}, {"id": "f4", "type": "textarea", "label": "When we will read them"}]'::jsonb, array['parenting', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('calm-response-role-play-game', 'Calm Response Role Play Game', 'game'::resource_kind, 'Parents take turns drawing scenarios and practicing a calm response.', 'Use it to help parents rehearse calm replies to tough moments.', array['Adults', 'Groups']::text[], '35 minutes', 'Make cards of common moments like refusing homework. Parents take turns playing the child and the parent. Others give feedback on what worked. Debrief on what made calm hard and what helps. Allow passing.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "My calm response"}, {"id": "f2", "type": "textarea", "label": "What the group said helped"}, {"id": "f3", "type": "textarea", "label": "What was hardest"}, {"id": "f4", "type": "textarea", "label": "What I will try at home"}]'::jsonb, array['parenting', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('co-parent-alignment-conversation-sheet', 'Co-Parent Alignment Conversation Sheet', 'couples'::resource_kind, 'A sheet for co-parents to talk about rules, roles and support.', 'Use it to help co-parents get on the same page and support each other.', array['Couples']::text[], '40 minutes', 'Each parent lists the top three rules they care about. Compare lists and discuss where they differ with curiosity. Agree on a short plan and how to back each other up in front of the child. Raise only issues that are safe to discuss together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the three rules I care about most"}, {"id": "f1", "type": "textarea", "label": "Partner B: the three rules I care about most"}, {"id": "f2", "type": "textarea", "label": "Where we differ"}, {"id": "f3", "type": "textarea", "label": "What we agree on"}, {"id": "f4", "type": "textarea", "label": "How we back each other up"}, {"id": "f5", "type": "textarea", "label": "When we will check in"}]'::jsonb, array['parenting', 'couples', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('validation-phrases-for-parents-practice', 'Validation Phrases for Parents Practice', 'dbt'::resource_kind, 'A practice sheet for validating a child''s feelings before problem solving.', 'Use it to help parents practice validating phrases.', array['Adults']::text[], '25 minutes', 'Share a short list of validating phrases and practice with real examples. Distinguish validation from agreeing or giving in. Have the parent role-play with you, then try it once at home.', '[{"id": "f0", "type": "textarea", "label": "A time my child was upset"}, {"id": "f1", "type": "textarea", "label": "What I usually say"}, {"id": "f2", "type": "textarea", "label": "A validating phrase I could use"}, {"id": "f3", "type": "textarea", "label": "What I want to do after validating"}, {"id": "f4", "type": "textarea", "label": "How it went when I tried"}]'::jsonb, array['parenting', 'core DBT', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('night-shift-sharing-and-rest-block-planner', 'Night Shift Sharing and Rest Block Planner', 'worksheet'::resource_kind, 'A planner for dividing nights and daytime rest among people who can help.', 'Use it to help a new parent find protected rest and support.', array['Adults', 'Couples']::text[], '30 minutes', 'List who can help and when, including partners, relatives and friends. Plan a block of rest for the client every day. Ask about what feels hard to ask for. If the client talks about thoughts of harming themselves or the baby, address it right away in session and share that 988 (call or text) is there any time.', '[{"id": "f0", "type": "textarea", "label": "People who can help"}, {"id": "f1", "type": "textarea", "label": "Times I need rest most"}, {"id": "f2", "type": "textarea", "label": "A protected rest block"}, {"id": "f3", "type": "textarea", "label": "What I find hard to ask for"}, {"id": "f4", "type": "textarea", "label": "How I will ask"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['perinatal and postpartum', 'support', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('mom-guilt-thought-review', 'Mom Guilt Thought Review', 'cbt'::resource_kind, 'A review of guilt thoughts about parenting with a fairer look at standards.', 'Use it to help a parent look at guilt-driven thoughts about parenting.', array['Adults']::text[], '25 minutes', 'Collect the ''should'' thoughts the parent has about feeding, sleep or time. Ask where the standard comes from and how a friend would judge it. Write a fairer thought. Avoid arguing the parent out of feelings.', '[{"id": "f0", "type": "textarea", "label": "The guilt thought"}, {"id": "f1", "type": "textarea", "label": "Where the standard comes from"}, {"id": "f2", "type": "textarea", "label": "What I would tell a friend"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}, {"id": "f4", "type": "textarea", "label": "What I will do for myself"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('new-baby-roles-and-appreciation-talk', 'New Baby Roles and Appreciation Talk', 'couples'::resource_kind, 'A conversation guide for two partners adjusting to a new baby.', 'Use it to help partners share the load and notice each other''s efforts.', array['Couples']::text[], '40 minutes', 'Each partner lists what they are carrying and what they appreciate in the other. Then plan one change. Keep it kind. Encourage them to name needs rather than keep score.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I carry"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I carry"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I appreciate"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I appreciate"}, {"id": "f4", "type": "textarea", "label": "One change we will try"}, {"id": "f5", "type": "textarea", "label": "When we will talk again"}]'::jsonb, array['perinatal and postpartum', 'couples', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('values-in-the-fog-of-new-parenthood-page', 'Values in the Fog of New Parenthood Page', 'act'::resource_kind, 'A page for naming what matters now and tiny actions that fit.', 'Use it to help a parent connect with values when time and energy are scarce.', array['Adults']::text[], '25 minutes', 'Ask the parent what kind of parent and person they want to be. Choose one tiny action per day. Accept that some days will be survival. Check in on feelings and ask about safety when needed, mentioning 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "What I value as a parent"}, {"id": "f1", "type": "textarea", "label": "What I value as a person"}, {"id": "f2", "type": "textarea", "label": "A tiny action for today"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "How I will be kind to myself"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['perinatal and postpartum', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('soothe-myself-between-feedings-plan', 'Soothe Myself Between Feedings Plan', 'dbt'::resource_kind, 'A plan of self-soothing through the senses for short breaks.', 'Use it to help a parent calm themselves in small windows.', array['Adults']::text[], '20 minutes', 'List sensory comforts that take under five minutes. Choose one for each of the five senses. Practice one in session. Ask where the parent can keep a small comfort kit.', '[{"id": "f0", "type": "textarea", "label": "Something to see that soothes me"}, {"id": "f1", "type": "textarea", "label": "Something to hear"}, {"id": "f2", "type": "textarea", "label": "Something to touch"}, {"id": "f3", "type": "textarea", "label": "Something to smell or taste"}, {"id": "f4", "type": "textarea", "label": "Where I will keep it"}]'::jsonb, array['perinatal and postpartum', 'core DBT', 'distress tolerance']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('core-belief-evidence-journal', 'Core Belief Evidence Journal', 'cbt'::resource_kind, 'A journal collecting evidence that supports a kinder belief about oneself.', 'Use it to help a client build a fairer view of themselves over time.', array['Adults']::text[], 'Five minutes daily', 'Choose one harsh belief and a more balanced one. Each day the client writes a piece of evidence for the balanced belief. Be patient; beliefs shift slowly. Review entries and celebrate small shifts.', '[{"id": "f0", "type": "textarea", "label": "The harsh belief"}, {"id": "f1", "type": "textarea", "label": "A kinder belief I want to test"}, {"id": "f2", "type": "textarea", "label": "Evidence today for the kinder belief"}, {"id": "f3", "type": "textarea", "label": "How much I believe it from 0 to 100"}, {"id": "f4", "type": "textarea", "label": "What I will look for tomorrow"}]'::jsonb, array['self-esteem', 'core CBT', 'thinking traps']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('self-worth-is-not-a-report-card-page', 'Self-Worth Is Not a Report Card Page', 'act'::resource_kind, 'A page separating worth from performance and linking to values.', 'Use it to help a client act on values without needing a perfect score.', array['Adults']::text[], '25 minutes', 'Ask where the client learned to measure worth by results. Name a value and an action that matters regardless of outcome. Keep the tone gentle.', '[{"id": "f0", "type": "textarea", "label": "How I measure my worth"}, {"id": "f1", "type": "textarea", "label": "Where I learned that"}, {"id": "f2", "type": "textarea", "label": "What I value that is not a result"}, {"id": "f3", "type": "textarea", "label": "An action I can take no matter the outcome"}, {"id": "f4", "type": "textarea", "label": "What I say to myself when I fall short"}]'::jsonb, array['self-esteem', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('i-am-great-at-poster', 'I Am Great At Poster', 'kids'::resource_kind, 'The child makes a poster of strengths with the help of a parent''s words.', 'Use it to help a child see what they do well.', array['Children']::text[], '30 minutes', 'The child writes or draws strengths on a poster and the parent adds a note. Display it at home. Tell the parent to praise effort and character. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my poster"}, {"id": "f1", "type": "textarea", "label": "Three things I am good at"}, {"id": "f2", "type": "textarea", "label": "Something kind I did"}, {"id": "f3", "type": "textarea", "label": "What my grown-up says about me"}, {"id": "f4", "type": "textarea", "label": "Where I will hang it"}]'::jsonb, array['self-esteem', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('strength-spotting-circle-game', 'Strength Spotting Circle Game', 'game'::resource_kind, 'Players spot strengths in each other with cards and give appreciations.', 'Use it to help a group notice and accept strengths.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Each player draws a strength card and offers a real appreciation to another. The receiver says thank you. Debrief on how it felt to give and to receive. Make passing available.', '[{"id": "f0", "type": "textarea", "label": "The strength I spotted"}, {"id": "f1", "type": "textarea", "label": "What I said"}, {"id": "f2", "type": "textarea", "label": "What I heard about myself"}, {"id": "f3", "type": "textarea", "label": "How it felt to receive"}, {"id": "f4", "type": "textarea", "label": "One strength I will own"}]'::jsonb, array['self-esteem', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('inner-critic-interview-page', 'Inner Critic Interview Page', 'worksheet'::resource_kind, 'An interview with the inner critic: what it says, why and what it is afraid of.', 'Use it to help a client understand the intent behind the critic.', array['Adults']::text[], '25 minutes', 'Ask the client to give the critic a name and ask what it wants. Often it is protecting. Then ask what a gentler coach would say. Do not try to silence it.', '[{"id": "f0", "type": "textarea", "label": "The name of my critic"}, {"id": "f1", "type": "textarea", "label": "What it says most"}, {"id": "f2", "type": "textarea", "label": "What it is trying to protect me from"}, {"id": "f3", "type": "textarea", "label": "What it costs me"}, {"id": "f4", "type": "textarea", "label": "What a kind coach would say"}]'::jsonb, array['self-esteem', 'self-compassion', 'thinking traps']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('social-prediction-test-sheet', 'Social Prediction Test Sheet', 'cbt'::resource_kind, 'A sheet for predicting how a social situation will go, then testing it.', 'Use it to help a client check predictions against what happens.', array['Adults']::text[], 'Full session', 'Pick a small social task. Record predictions, safety behaviors and outcomes. Ask what the client noticed about others. Keep tasks gradual and agreed on.', '[{"id": "f0", "type": "textarea", "label": "The social situation"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "Safety behaviors I will drop"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I noticed about other people"}, {"id": "f5", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('connection-value-single-step-page', 'Connection Value Single Step Page', 'act'::resource_kind, 'A page for choosing connection as a value and one step despite fear.', 'Use it to help a client move toward connection while anxious.', array['Adults']::text[], '25 minutes', 'Ask what connection means to the client. Pick a step like greeting someone. Name the thoughts that will come and decide to carry them. Review what happened.', '[{"id": "f0", "type": "textarea", "label": "What connection means to me"}, {"id": "f1", "type": "textarea", "label": "A small social step"}, {"id": "f2", "type": "textarea", "label": "Thoughts that will come"}, {"id": "f3", "type": "textarea", "label": "Feelings I will carry"}, {"id": "f4", "type": "textarea", "label": "What I did"}, {"id": "f5", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('opener-and-follow-up-pairing-game', 'Opener and Follow-Up Pairing Game', 'game'::resource_kind, 'Players practice starters and follow-up questions with cards.', 'Use it to help players try conversation starters in a low-stakes game.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Make cards with openers and follow-ups. Players pair up and practice for two minutes, then swap. Debrief on what felt natural. Passing is fine.', '[{"id": "f0", "type": "textarea", "label": "The opener I drew"}, {"id": "f1", "type": "textarea", "label": "How the chat went"}, {"id": "f2", "type": "textarea", "label": "A follow-up I liked"}, {"id": "f3", "type": "textarea", "label": "What was hard"}, {"id": "f4", "type": "textarea", "label": "Where I will use it"}]'::jsonb, array['social anxiety', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('attention-inside-and-out-experiment-page', 'Attention Inside and Out Experiment Page', 'worksheet'::resource_kind, 'A page comparing focusing on oneself with focusing on the other person.', 'Use it to help a client notice how self-focus affects anxiety in conversation.', array['Adults']::text[], '25 minutes', 'Run a short conversation in session twice, once focusing inward and once outward. Rate anxiety and connection each time. Discuss what changed. Repeat outside session.', '[{"id": "f0", "type": "textarea", "label": "How I felt focusing on myself"}, {"id": "f1", "type": "textarea", "label": "How I felt focusing on the other person"}, {"id": "f2", "type": "textarea", "label": "What I noticed about the conversation"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "Where I will practice"}]'::jsonb, array['social anxiety', 'attention', 'behavioral experiment']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('interpersonal-confidence-script-card', 'Interpersonal Confidence Script Card', 'dbt'::resource_kind, 'A card with short scripts for asking, saying no and joining a group.', 'Use it to give a client words to use in social moments.', array['Adults', 'Teens']::text[], '30 minutes', 'Draft scripts with the client using DEAR MAN steps. Practice in role play. Keep scripts short and in their own voice. Give feedback on tone.', '[{"id": "f0", "type": "textarea", "label": "A situation where I want to speak up"}, {"id": "f1", "type": "textarea", "label": "What I want to say"}, {"id": "f2", "type": "textarea", "label": "How I will say it"}, {"id": "f3", "type": "textarea", "label": "My tone and posture"}, {"id": "f4", "type": "textarea", "label": "How it went in practice"}]'::jsonb, array['social anxiety', 'interpersonal effectiveness', 'DEAR MAN']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('grief-wave-notes', 'Grief Wave Notes', 'worksheet'::resource_kind, 'A page for noticing grief waves, what set them off and what helped.', 'Use it to help a client see grief as something that comes and goes.', array['Adults']::text[], '20 minutes', 'Ask the client to record when waves come and what comforts. Normalize that grief has no schedule. Do not push toward closure. Ask about safety if the client feels hopeless and share that 988 (call or text) is open any time.', '[{"id": "f0", "type": "textarea", "label": "When a wave came"}, {"id": "f1", "type": "textarea", "label": "What set it off"}, {"id": "f2", "type": "textarea", "label": "What it felt like"}, {"id": "f3", "type": "textarea", "label": "What helped"}, {"id": "f4", "type": "textarea", "label": "Who I reached out to"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['grief and loss', 'support', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-i-loved-and-how-i-honor-it-page', 'What I Loved and How I Honor It Page', 'act'::resource_kind, 'A page linking what the client loved about the person with ways to honor it.', 'Use it to help a client carry values and love forward after a loss.', array['Adults']::text[], '30 minutes', 'Ask what the person valued and what the client values about them. Choose one small act that honors that. Let the client set the pace and allow tears.', '[{"id": "f0", "type": "textarea", "label": "What I loved about them"}, {"id": "f1", "type": "textarea", "label": "What they valued"}, {"id": "f2", "type": "textarea", "label": "A way to honor that"}, {"id": "f3", "type": "textarea", "label": "What makes it hard"}, {"id": "f4", "type": "textarea", "label": "What I will do and when"}]'::jsonb, array['grief and loss', 'values', 'connection']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('keepsake-box-for-a-missed-person-or-pet', 'Keepsake Box for a Missed Person or Pet', 'kids'::resource_kind, 'The child decorates a box and fills it with drawings and keepsakes of someone they miss.', 'Use it to give a child a safe way to remember a person or pet.', array['Children']::text[], '30 minutes', 'The child decorates a box and picks items. Let them talk or stay quiet. Tell the parent that questions and repeated sadness are common and to answer honestly in simple words. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my memory box"}, {"id": "f1", "type": "textarea", "label": "What I put in it"}, {"id": "f2", "type": "textarea", "label": "A good memory"}, {"id": "f3", "type": "textarea", "label": "How I feel today"}, {"id": "f4", "type": "textarea", "label": "Who I can talk to"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('two-ways-of-mourning-partner-talk-guide', 'Two Ways of Mourning Partner Talk Guide', 'couples'::resource_kind, 'A guide for partners who grieve in different ways to share and support.', 'Use it to help partners understand each other''s different grieving.', array['Couples']::text[], '40 minutes', 'Each partner describes how they grieve and what they need. Listen without comparing. Choose one shared ritual and one space for solo time.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve"}, {"id": "f2", "type": "textarea", "label": "What I need from you"}, {"id": "f3", "type": "textarea", "label": "What I find hard to see in you"}, {"id": "f4", "type": "textarea", "label": "A shared ritual"}, {"id": "f5", "type": "textarea", "label": "A way to give each other space"}]'::jsonb, array['grief and loss', 'couples', 'support']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('story-stones-remembering-game', 'Story Stones Remembering Game', 'game'::resource_kind, 'Players choose stones with pictures and share a memory or feeling.', 'Use it to help a group remember and share at their own pace.', array['Adults', 'Groups']::text[], '30 minutes', 'Paint simple pictures on stones. Players draw one and share a memory if they wish. Others listen without fixing. Debrief on what it was like.', '[{"id": "f0", "type": "textarea", "label": "The stone I drew"}, {"id": "f1", "type": "textarea", "label": "The memory it brought"}, {"id": "f2", "type": "textarea", "label": "How I felt sharing"}, {"id": "f3", "type": "textarea", "label": "What I heard from others"}, {"id": "f4", "type": "textarea", "label": "What I will take with me"}]'::jsonb, array['grief and loss', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('softened-startup-practice-sheet', 'Softened Startup Practice Sheet', 'couples'::resource_kind, 'A sheet for rewording complaints into gentle requests.', 'Use it to help partners begin tough talks with less blame.', array['Couples']::text[], '30 minutes', 'Take a complaint and rewrite it as ''I feel... about... and I need...''. Practice aloud. Give feedback on tone. Note the difference in how it lands.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my complaint as I would usually say it"}, {"id": "f1", "type": "textarea", "label": "Partner A: my softened version"}, {"id": "f2", "type": "textarea", "label": "Partner B: my complaint as I would usually say it"}, {"id": "f3", "type": "textarea", "label": "Partner B: my softened version"}, {"id": "f4", "type": "textarea", "label": "How each version felt to hear"}]'::jsonb, array['relationship issues', 'couples', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('dear-man-relationship-request-page', 'DEAR MAN Relationship Request Page', 'dbt'::resource_kind, 'A page for planning a clear, respectful request in a relationship.', 'Use it to help a client ask for what they need with skill.', array['Adults']::text[], '30 minutes', 'Walk through each step: Describe, Express, Assert, Reinforce, Mindful, Appear confident, Negotiate. Role play the request. Plan for different responses.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "Describe the facts"}, {"id": "f2", "type": "textarea", "label": "Express my feelings"}, {"id": "f3", "type": "textarea", "label": "Assert what I ask"}, {"id": "f4", "type": "textarea", "label": "What I offer in return"}, {"id": "f5", "type": "textarea", "label": "How I will respond if they say no"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('guess-about-their-thoughts-ask-first-page', 'Guess About Their Thoughts Ask-First Page', 'cbt'::resource_kind, 'A page for catching assumptions about a partner''s thoughts and checking them.', 'Use it to help a client check guesses about what others think.', array['Adults']::text[], '20 minutes', 'List the assumption and how it affected behavior. Brainstorm other explanations. Plan a way to ask. Practice the question in session.', '[{"id": "f0", "type": "textarea", "label": "What I assumed"}, {"id": "f1", "type": "textarea", "label": "How it changed what I did"}, {"id": "f2", "type": "textarea", "label": "Other explanations"}, {"id": "f3", "type": "textarea", "label": "A question I can ask"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['relationship issues', 'thinking traps', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('needs-and-wants-trading-game', 'Needs and Wants Trading Game', 'game'::resource_kind, 'Players trade cards of needs and wants and discuss what they are willing to give.', 'Use it to help players talk about needs and compromise playfully.', array['Adults', 'Groups']::text[], '30 minutes', 'Make cards for needs like quiet time or affection. Players trade with partners and explain choices. Debrief on what was hard to give or ask. Keep it kind.', '[{"id": "f0", "type": "textarea", "label": "The cards I traded"}, {"id": "f1", "type": "textarea", "label": "What I asked for"}, {"id": "f2", "type": "textarea", "label": "What I gave"}, {"id": "f3", "type": "textarea", "label": "What was hard"}, {"id": "f4", "type": "textarea", "label": "What I will try in real life"}]'::jsonb, array['relationship issues', 'game', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('closeness-and-conflict-patterns-strip', 'Closeness and Conflict Patterns Strip', 'worksheet'::resource_kind, 'A timeline of how the client has acted in past relationships and what they want next.', 'Use it to help a client see patterns and choose different steps.', array['Adults']::text[], '35 minutes', 'Ask for a few moments, not full histories. Notice patterns in how they handle closeness and conflict. Focus on what they want now and one new step.', '[{"id": "f0", "type": "textarea", "label": "Moments that stand out"}, {"id": "f1", "type": "textarea", "label": "Patterns I notice"}, {"id": "f2", "type": "textarea", "label": "What I did well"}, {"id": "f3", "type": "textarea", "label": "What I want to do differently"}, {"id": "f4", "type": "textarea", "label": "One new step"}]'::jsonb, array['relationship issues', 'patterns', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('today-s-safe-people-and-places-plan-page', 'Today''s Safe People and Places Plan Page', 'worksheet'::resource_kind, 'A page naming safe people, places and steps without recounting any events.', 'Use it to help a client build a current-day plan for safety and support.', array['Adults', 'Teens']::text[], '30 minutes', 'Focus on the present: who is safe, where, and what to do when feeling unsafe. Never ask for details of the past. Check reporting duties if the client is a minor. Share that 988 (call or text) is available any time, and RAINN at 800-656-4673.', '[{"id": "f0", "type": "textarea", "label": "People I trust"}, {"id": "f1", "type": "textarea", "label": "Places where I feel safe"}, {"id": "f2", "type": "textarea", "label": "What I do when I feel unsafe"}, {"id": "f3", "type": "textarea", "label": "Who I can call"}, {"id": "f4", "type": "textarea", "label": "Steps for a hard day"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('grounding-and-pacing-skills-menu', 'Grounding and Pacing Skills Menu', 'dbt'::resource_kind, 'A menu of grounding and pacing skills to use before and after session.', 'Use it to help a client slow down and stay present.', array['Adults']::text[], '25 minutes', 'Try several skills in session and let the client rate them. Agree on a pace and a stop signal. Nothing here asks for details of what happened. Check in at the end.', '[{"id": "f0", "type": "textarea", "label": "Skills that ground me"}, {"id": "f1", "type": "textarea", "label": "Skills that help me slow down"}, {"id": "f2", "type": "textarea", "label": "My stop signal"}, {"id": "f3", "type": "textarea", "label": "What I do after a session"}, {"id": "f4", "type": "textarea", "label": "Who I can contact"}]'::jsonb, array['sexual abuse', 'grounding', 'core DBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('reclaiming-choices-values-page', 'Reclaiming Choices Values Page', 'act'::resource_kind, 'A page about choices the client can make now that fit their values.', 'Use it to help a client notice choice and agency in daily life.', array['Adults']::text[], '30 minutes', 'Invite the client to list small daily choices that are theirs. Link to values. Go slowly and let them skip anything. Never ask about past events.', '[{"id": "f0", "type": "textarea", "label": "Small choices that are mine"}, {"id": "f1", "type": "textarea", "label": "What I value"}, {"id": "f2", "type": "textarea", "label": "A choice I want to make this week"}, {"id": "f3", "type": "textarea", "label": "What supports me"}, {"id": "f4", "type": "textarea", "label": "What I will do if it feels hard"}]'::jsonb, array['sexual abuse', 'values', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-safety-rules-drawing', 'Body Safety Rules Drawing', 'kids'::resource_kind, 'The child draws the people and rules that keep their body safe and who to tell.', 'Use it to help a child learn safety rules and trusted adults.', array['Children']::text[], '25 minutes', 'Use simple, age-appropriate language: my body belongs to me, and I can always tell a trusted adult. Do not ask for details. Tell the parent how to respond calmly if a child shares. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw me and my safe grown-ups"}, {"id": "f1", "type": "textarea", "label": "Who I can tell"}, {"id": "f2", "type": "textarea", "label": "The rule about my body"}, {"id": "f3", "type": "textarea", "label": "What I do if someone makes me feel unsafe"}, {"id": "f4", "type": "textarea", "label": "What my grown-up says"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fair-thoughts-about-blame-cards', 'Fair Thoughts About Blame Cards', 'cbt'::resource_kind, 'Cards for gently looking at self-blame thoughts and finding fairer ones.', 'Use it to help a client meet self-blame thoughts with kindness.', array['Adults']::text[], '25 minutes', 'Work only with thoughts, not events. Ask the client what they would tell a friend. Write a fairer thought and practice reading it. Skip if the client feels unsteady. Share that 988 (call or text) is available.', '[{"id": "f0", "type": "textarea", "label": "A blame thought that visits me"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f2", "type": "textarea", "label": "A fairer thought"}, {"id": "f3", "type": "textarea", "label": "How I feel reading it"}, {"id": "f4", "type": "textarea", "label": "Who supports me"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['sexual abuse', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('tipp-skills-practice-log', 'TIPP Skills Practice Log', 'dbt'::resource_kind, 'A log for practicing temperature, intense exercise, paced breathing and relaxation.', 'Use it to help a client try body-based skills for fast relief.', array['Adults']::text[], 'One week, ten minutes per entry', 'Teach each skill and rate it in session. Ask the client to log use and effect. Check for health issues before temperature or exercise skills.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "Which TIPP skill I used"}, {"id": "f2", "type": "textarea", "label": "Distress before"}, {"id": "f3", "type": "textarea", "label": "Distress after"}, {"id": "f4", "type": "textarea", "label": "What I would change"}]'::jsonb, array['coping skills', 'distress tolerance', 'core DBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('room-hunt-for-everyday-calm-tools', 'Room Hunt for Everyday Calm Tools', 'game'::resource_kind, 'Players hunt for items and places that support coping skills and share how they use them.', 'Use it to help players find coping tools around them.', array['Teens', 'Adults', 'Groups']::text[], '35 minutes', 'Make a list like something soft, something that smells nice, a quiet spot. Players find them and explain use. Debrief on which they will use.', '[{"id": "f0", "type": "textarea", "label": "What I found"}, {"id": "f1", "type": "textarea", "label": "How I could use it"}, {"id": "f2", "type": "textarea", "label": "What surprised me"}, {"id": "f3", "type": "textarea", "label": "What I will keep"}, {"id": "f4", "type": "textarea", "label": "Where I will use it"}]'::jsonb, array['coping skills', 'game', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('decorate-and-fill-my-calm-tool-box', 'Decorate and Fill My Calm Tool Box', 'kids'::resource_kind, 'The child decorates a box and fills it with coping tools they pick.', 'Use it to help a child build a personal set of coping tools.', array['Children']::text[], '30 minutes', 'The child decorates a box and adds drawings or small items like a stress ball. Practice using each. Tell the parent to keep it handy. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my toolbox"}, {"id": "f1", "type": "textarea", "label": "Tools I put in"}, {"id": "f2", "type": "textarea", "label": "Which tool I use first"}, {"id": "f3", "type": "textarea", "label": "When I will use it"}, {"id": "f4", "type": "textarea", "label": "How my grown-up helps"}]'::jsonb, array['coping skills', 'children', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('hard-moment-to-skill-pairing-chart', 'Hard Moment to Skill Pairing Chart', 'worksheet'::resource_kind, 'A chart matching feelings and situations with coping skills.', 'Use it to help a client match skills to what they face.', array['Adults', 'Teens']::text[], '25 minutes', 'List common difficult moments and brainstorm skills. Rate each match from 0 to 10. Revise after trying them.', '[{"id": "f0", "type": "textarea", "label": "A hard situation"}, {"id": "f1", "type": "textarea", "label": "Skills that might fit"}, {"id": "f2", "type": "textarea", "label": "My rating of each"}, {"id": "f3", "type": "textarea", "label": "The one I will try"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['coping skills', 'skills', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('willingness-to-feel-practice-page', 'Willingness to Feel Practice Page', 'act'::resource_kind, 'A page practicing making room for a feeling for a short time.', 'Use it to help a client build willingness to feel without escape.', array['Adults']::text[], '20 minutes', 'Choose a mild feeling and have the client stay with it for a minute, noticing sensations. Rate willingness. Debrief gently.', '[{"id": "f0", "type": "textarea", "label": "The feeling I picked"}, {"id": "f1", "type": "textarea", "label": "Where I notice it"}, {"id": "f2", "type": "textarea", "label": "How willing I was"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "How I might use this"}]'::jsonb, array['coping skills', 'willingness', 'core ACT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('feared-situations-rung-ranking-page', 'Feared Situations Rung Ranking Page', 'cbt'::resource_kind, 'A ladder of feared situations ranked from easiest to hardest.', 'Use it to help a client plan gradual steps toward a feared situation.', array['Adults']::text[], 'Full session', 'List situations and rate fear for each. Pick a first step that is challenging but doable. Plan how to stay in it. Agree on pacing together.', '[{"id": "f0", "type": "textarea", "label": "The fear I want to work on"}, {"id": "f1", "type": "textarea", "label": "Situations ranked by fear"}, {"id": "f2", "type": "textarea", "label": "My first step"}, {"id": "f3", "type": "textarea", "label": "How long I will stay"}, {"id": "f4", "type": "textarea", "label": "What I notice after"}]'::jsonb, array['phobias', 'exposure', 'avoidance']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('sticker-ladder-of-brave-small-steps', 'Sticker Ladder of Brave Small Steps', 'kids'::resource_kind, 'The child decorates a ladder with small brave steps and stickers.', 'Use it to help a child take small steps toward something scary.', array['Children']::text[], '25 minutes', 'The child draws a ladder with steps from easy to hard. Add stickers after each step. Tell the parent to cheer effort and never force a step. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my ladder"}, {"id": "f1", "type": "textarea", "label": "My first step"}, {"id": "f2", "type": "textarea", "label": "Who helps me"}, {"id": "f3", "type": "textarea", "label": "How I feel after a step"}, {"id": "f4", "type": "textarea", "label": "What I get to do after"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fear-facing-board-game', 'Fear Facing Board Game', 'game'::resource_kind, 'Players move along a board and take on small fear-facing challenges.', 'Use it to help a group try small exposures with support.', array['Teens', 'Adults', 'Groups']::text[], '40 minutes', 'Create a board with challenge squares at mild levels. Players choose challenges and cheer each other. Debrief on what it was like. Always allow a pass.', '[{"id": "f0", "type": "textarea", "label": "The challenge I took"}, {"id": "f1", "type": "textarea", "label": "How scared I felt"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "The next challenge"}]'::jsonb, array['phobias', 'game', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-i-skip-because-of-fear-map', 'What I Skip Because of Fear Map', 'worksheet'::resource_kind, 'A map of things the client avoids because of a fear and what it costs.', 'Use it to help a client see how avoidance shapes daily life.', array['Adults']::text[], '25 minutes', 'List places and activities avoided. Ask what each costs. Choose one to work toward. Keep non-judgmental.', '[{"id": "f0", "type": "textarea", "label": "Things I avoid"}, {"id": "f1", "type": "textarea", "label": "What I miss out on"}, {"id": "f2", "type": "textarea", "label": "What I fear will happen"}, {"id": "f3", "type": "textarea", "label": "One thing I want back"}, {"id": "f4", "type": "textarea", "label": "A first step"}]'::jsonb, array['phobias', 'avoidance', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fear-and-values-crossroads-page', 'Fear and Values Crossroads Page', 'act'::resource_kind, 'A page for choosing values-led action when fear points elsewhere.', 'Use it to help a client choose a valued direction with fear present.', array['Adults']::text[], '25 minutes', 'Draw a crossroads with fear on one path and values on the other. Discuss what each gives. Choose a step and plan to carry the fear.', '[{"id": "f0", "type": "textarea", "label": "What fear tells me to do"}, {"id": "f1", "type": "textarea", "label": "What my values point to"}, {"id": "f2", "type": "textarea", "label": "The cost of each path"}, {"id": "f3", "type": "textarea", "label": "The step I will take"}, {"id": "f4", "type": "textarea", "label": "What I will carry with me"}]'::jsonb, array['phobias', 'values', 'willingness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-talk-thought-record', 'Body Talk Thought Record', 'cbt'::resource_kind, 'A thought record for noticing critical thoughts about the body and shifting them.', 'Use it to help a client catch critical body thoughts and find a fairer view.', array['Adults']::text[], '25 minutes', 'Ask the client to notice when body thoughts spike and what was happening. Write a fairer thought focusing on what the body does. Avoid discussing size, shape or appearance rules.', '[{"id": "f0", "type": "textarea", "label": "Where I was when the thought came"}, {"id": "f1", "type": "textarea", "label": "The thought"}, {"id": "f2", "type": "textarea", "label": "How it made me feel"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}, {"id": "f4", "type": "textarea", "label": "What my body did for me today"}]'::jsonb, array['body image', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-as-a-home-values-page', 'Body as a Home Values Page', 'act'::resource_kind, 'A page about caring for and appreciating the body as the home where life happens.', 'Use it to help a client act on values rather than appearance.', array['Adults']::text[], '25 minutes', 'Ask what the client''s body lets them do. Link to values and plan one caring act. Keep focus on function and care.', '[{"id": "f0", "type": "textarea", "label": "What my body lets me do"}, {"id": "f1", "type": "textarea", "label": "What I value"}, {"id": "f2", "type": "textarea", "label": "One caring act this week"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "How I will notice"}]'::jsonb, array['body image', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-judgment-letting-go-practice', 'Body Judgment Letting-Go Practice', 'dbt'::resource_kind, 'A mindfulness practice for noticing body judgments without acting on them.', 'Use it to help a client observe judgments and return to the present.', array['Adults']::text[], '20 minutes', 'Teach non-judgmental stance. Have the client notice a judgment, label it ''judgment'' and return to the senses. Practice in session.', '[{"id": "f0", "type": "textarea", "label": "A judgment I noticed"}, {"id": "f1", "type": "textarea", "label": "How I labeled it"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my senses"}, {"id": "f3", "type": "textarea", "label": "How I returned"}, {"id": "f4", "type": "textarea", "label": "When I will practice"}]'::jsonb, array['body image', 'core DBT', 'mindfulness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('appreciation-for-who-we-are-exchange', 'Appreciation for Who We Are Exchange', 'couples'::resource_kind, 'Partners trade appreciation about character and shared moments, not looks.', 'Use it to help partners value each other beyond appearance.', array['Couples']::text[], '25 minutes', 'Each writes appreciations about qualities and actions. Read aloud and receive. Debrief on what it felt like. Keep appearance out.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I appreciate about my partner"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I appreciate about my partner"}, {"id": "f2", "type": "textarea", "label": "How it felt to hear"}, {"id": "f3", "type": "textarea", "label": "A moment I treasure"}, {"id": "f4", "type": "textarea", "label": "How we will keep it up"}]'::jsonb, array['body image', 'couples', 'connection']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-my-body-does-collage', 'What My Body Does Collage', 'kids'::resource_kind, 'The child makes a collage of all the things their body does and loves.', 'Use it to help a child value what their body can do.', array['Children']::text[], '30 minutes', 'The child cuts pictures or draws activities like running, hugging and laughing. Tell the parent to talk about what bodies do, not how they look. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my collage"}, {"id": "f1", "type": "textarea", "label": "Things my body does"}, {"id": "f2", "type": "textarea", "label": "My favorite"}, {"id": "f3", "type": "textarea", "label": "How my body helps me"}, {"id": "f4", "type": "textarea", "label": "What my grown-up says"}]'::jsonb, array['body image', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('reentry-after-leave-planner', 'Reentry After Leave Planner', 'worksheet'::resource_kind, 'A one-page plan for the first week back at work or school after time away.', 'Use it to help a client return from a leave with a paced first week instead of a full plunge.', array['Adults', 'Teens']::text[], '30 minutes', 'Build the plan a week before the return date. Ask what the client dreads about the first day, then fill in who already knows they were away, what they will say in one sentence if asked, and which tasks can wait until the second week. Most clients overcommit on day one; look at the plan together after the first few days and trim it again.', '[{"id": "f0", "type": "textarea", "label": "The date I go back, and the three things I will do on the first morning:"}, {"id": "f1", "type": "textarea", "label": "One sentence I can say if someone asks where I have been:"}, {"id": "f2", "type": "textarea", "label": "Tasks I will let wait until the second week:"}, {"id": "f3", "type": "textarea", "label": "Who I can check in with at the end of the first day:"}, {"id": "f4", "type": "textarea", "label": "How I will know the week was good enough:"}]'::jsonb, array['transitions', 'planning', 'pacing']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('noise-and-light-sensitivity-map', 'Noise and Light Sensitivity Map', 'worksheet'::resource_kind, 'A map of the sounds, lights and textures in daily life that drain the client, with one adjustment for each.', 'Use it to help a client see which parts of their environment cost them energy and what they can change.', array['Adults', 'Teens']::text[], '30 minutes', 'Walk through a typical day room by room and ask what the client hears, sees and feels against their skin. Many have never named a hum or a flicker as a cost. For each item that drains them, find one small adjustment they control: a lamp instead of overhead light, earbuds on the train, a softer shirt. Revisit after a week to see which changes stuck.', '[{"id": "f0", "type": "textarea", "label": "Sounds, lights or textures that wear on me at home:"}, {"id": "f1", "type": "textarea", "label": "The same list for work, school or the commute:"}, {"id": "f2", "type": "textarea", "label": "Which of these I can change, and how:"}, {"id": "f3", "type": "textarea", "label": "Which I cannot change, and how I will recover afterward:"}, {"id": "f4", "type": "textarea", "label": "One adjustment I will try this week:"}]'::jsonb, array['energy', 'body awareness', 'self-care']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('rumination-hot-spots-clock', 'Rumination Hot Spots Clock', 'worksheet'::resource_kind, 'A clock face the client shades to show when and where repetitive thinking takes hold.', 'Use it to show a client the times of day and places where looping thoughts are most likely, so plans can target them.', array['Adults', 'Teens']::text[], 'One week', 'Have the client draw a clock face and shade the hours when they notice going over the same thoughts, then note where they were and what they were doing. Over a week a pattern usually appears, often the shower, the commute or the hour before sleep. Use the hot spots to place a replacement activity or a planned worry window rather than fighting rumination everywhere at once.', '[{"id": "f0", "type": "textarea", "label": "Hours of the day I shaded as hot spots:"}, {"id": "f1", "type": "textarea", "label": "Where I usually am and what I am doing at those times:"}, {"id": "f2", "type": "textarea", "label": "What the loops are usually about:"}, {"id": "f3", "type": "textarea", "label": "One thing I could do differently in the biggest hot spot:"}, {"id": "f4", "type": "textarea", "label": "What I noticed after trying it for a few days:"}]'::jsonb, array['self-monitoring', 'worry', 'routines']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('hobby-rediscovery-inventory', 'Hobby Rediscovery Inventory', 'worksheet'::resource_kind, 'An inventory of interests the client once had, what ended them and which could return in a small form.', 'Use it to help a client find a lapsed interest worth restarting in a ten-minute version.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to list anything they used to do for its own sake, from childhood onward, without judging whether it was good or useful. Then ask what ended each one: time, money, a move, a person, a mood. Pick one that ended for a reason that no longer applies and shrink it to a ten-minute version they could try this week. The point is contact with the interest, not mastery.', '[{"id": "f0", "type": "textarea", "label": "Things I used to do just because I enjoyed them:"}, {"id": "f1", "type": "textarea", "label": "What ended each one:"}, {"id": "f2", "type": "textarea", "label": "Which of those reasons no longer apply:"}, {"id": "f3", "type": "textarea", "label": "The one I will try again, in its smallest ten-minute form:"}, {"id": "f4", "type": "textarea", "label": "When and where I will try it this week:"}]'::jsonb, array['behavioral activation', 'energy', 'planning']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('decision-regret-review-sheet', 'Decision Regret Review Sheet', 'worksheet'::resource_kind, 'A fair look back at a decision the client regrets, separating what they knew then from what they know now.', 'Use it to help a client review a regretted decision with the information they actually had at the time.', array['Adults']::text[], '30 minutes', 'Pick one decision the client keeps returning to. Write down what they knew, wanted and feared at the moment they decided, before adding anything learned since. Then list what hindsight added. Most regret runs on information that arrived later. Finish with one thing the client would carry into a similar decision, so the review ends in a lesson rather than a verdict.', '[{"id": "f0", "type": "textarea", "label": "The decision I keep going back to:"}, {"id": "f1", "type": "textarea", "label": "What I knew, wanted and feared at the time I made it:"}, {"id": "f2", "type": "textarea", "label": "What I only learned afterward:"}, {"id": "f3", "type": "textarea", "label": "What I would tell a friend who made the same choice with the same information:"}, {"id": "f4", "type": "textarea", "label": "One thing I will carry into the next decision like it:"}]'::jsonb, array['decisions', 'self-compassion', 'perspective']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('personalization-check-sheet', 'Personalization Check Sheet', 'cbt'::resource_kind, 'A sheet for catching the moment the client assumes someone else''s mood or outcome is about them.', 'Use it to help a client test the thought that another person''s reaction was caused by them.', array['Adults', 'Teens']::text[], '20 minutes', 'Start with a recent moment when the client felt responsible for someone else''s bad mood, silence or problem. Ask them to list every other reason that person might have reacted that way, then rate how much of the outcome was actually theirs. Personalizing feels like responsibility but usually skips the evidence. Pair this with a check-out question the client could ask the person.', '[{"id": "f0", "type": "textarea", "label": "What happened, and what I assumed it meant about me:"}, {"id": "f1", "type": "textarea", "label": "Other reasons this person might have reacted that way:"}, {"id": "f2", "type": "textarea", "label": "Out of ten, how much of this was actually about me:"}, {"id": "f3", "type": "textarea", "label": "A question I could ask to find out instead of guessing:"}, {"id": "f4", "type": "textarea", "label": "A fairer thought to hold until I know more:"}]'::jsonb, array['thinking traps', 'core CBT', 'relationships']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('binoculars-trick-thought-sheet', 'Binoculars Trick Thought Sheet', 'cbt'::resource_kind, 'A sheet for spotting when the client magnifies their flaws and shrinks their strengths, and turning the binoculars around.', 'Use it to help a client notice magnification and minimization in one situation and write the balanced view.', array['Adults', 'Teens']::text[], '20 minutes', 'Explain the two ends of the binoculars: one end makes a mistake enormous, the other makes a success tiny. Take a recent event and ask the client which end they used for each part. Then write what the event looks like at actual size, with the mistake and the success both in it. This lands best with clients who already know the thinking trap names and want a quicker tool.', '[{"id": "f0", "type": "textarea", "label": "The event I am thinking about:"}, {"id": "f1", "type": "textarea", "label": "What I made bigger than it was:"}, {"id": "f2", "type": "textarea", "label": "What I made smaller than it was:"}, {"id": "f3", "type": "textarea", "label": "The same event described at actual size:"}, {"id": "f4", "type": "textarea", "label": "How I feel reading the actual-size version:"}]'::jsonb, array['thinking traps', 'core CBT', 'self-criticism']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('favor-request-experiment-sheet', 'Favor Request Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment in asking one person for a small favor and recording what actually happens.', 'Use it to help a client test the prediction that asking for help will annoy people or be refused.', array['Adults', 'Teens']::text[], 'One week', 'Choose a favor small enough to ask this week and specific enough to be answered: a ride, a recipe, ten minutes of advice. Have the client write their prediction and how sure they are, then ask and record the response and their feeling afterward. Debrief what the result says about the prediction, and whether a second, slightly bigger ask is worth planning.', '[{"id": "f0", "type": "textarea", "label": "The favor I will ask for, and who I will ask:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen, and how sure I am out of ten:"}, {"id": "f2", "type": "textarea", "label": "What actually happened when I asked:"}, {"id": "f3", "type": "textarea", "label": "How I felt right after, and an hour later:"}, {"id": "f4", "type": "textarea", "label": "What this tells me about my prediction, and what I might ask next:"}]'::jsonb, array['behavioral experiment', 'core CBT', 'support']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('dreaded-phone-call-rehearsal-sheet', 'Dreaded Phone Call Rehearsal Sheet', 'cbt'::resource_kind, 'A rehearsal plan for one avoided phone call, with the opening line, the likely snags and the coping thought.', 'Use it to help a client make a call they have been putting off by scripting and rehearsing it in session.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick the call the client has avoided longest. Write the first sentence word for word, then the two or three turns the conversation might take and what the client will say at each. Rehearse it aloud in session, playing the other party. Set a time to make the call within a day of the session, while the rehearsal is fresh, and ask the client to note how it went.', '[{"id": "f0", "type": "textarea", "label": "The call I have been avoiding, and why it matters:"}, {"id": "f1", "type": "textarea", "label": "My first sentence, word for word:"}, {"id": "f2", "type": "textarea", "label": "The ways the call might go, and what I will say for each:"}, {"id": "f3", "type": "textarea", "label": "The thought that will keep me on the line if it gets awkward:"}, {"id": "f4", "type": "textarea", "label": "When I will make the call, and how it actually went:"}]'::jsonb, array['avoidance', 'core CBT', 'assertiveness']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('sunk-cost-thought-check', 'Sunk Cost Thought Check', 'cbt'::resource_kind, 'A thought check for staying in a job, plan or habit because of what has already been spent on it.', 'Use it to help a client separate what they have already invested from what the choice costs and gives from here.', array['Adults']::text[], '30 minutes', 'Name the thing the client feels they cannot leave because of the years, money or effort already put in. Write down what the choice gives and costs from today forward, leaving the past spending out of that column entirely. Then ask what they would advise a friend starting fresh today. The past cannot be recovered either way; the decision is only about what comes next.', '[{"id": "f0", "type": "textarea", "label": "What I feel I cannot walk away from, and what I have already put into it:"}, {"id": "f1", "type": "textarea", "label": "What staying gives me from today forward:"}, {"id": "f2", "type": "textarea", "label": "What staying costs me from today forward:"}, {"id": "f3", "type": "textarea", "label": "What I would tell a friend deciding this today, with nothing already invested:"}, {"id": "f4", "type": "textarea", "label": "The thought I will hold the next time the sunk cost argument shows up:"}]'::jsonb, array['decisions', 'thinking traps', 'core CBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('tin-can-monster-exercise-page', 'Tin Can Monster Exercise Page', 'act'::resource_kind, 'A guided exercise that takes a frightening feeling apart into sensations, thoughts, urges and memories one at a time.', 'Use it to help a client experience a big feeling as a collection of smaller, more workable parts.', array['Adults', 'Teens']::text[], 'Full session', 'Introduce the image of a monster made of tin cans and string that is only frightening when it is whole. Have the client bring up a moderately difficult feeling and then, one piece at a time, notice a body sensation, a thought, an urge and a memory, staying with each for a minute or two with willingness. Debrief which pieces were easiest and hardest to hold. Keep the intensity moderate; this is a willingness exercise, not a flooding one.', '[{"id": "f0", "type": "textarea", "label": "The feeling I worked with, and how big it felt before we started:"}, {"id": "f1", "type": "textarea", "label": "The body sensations I noticed, one at a time:"}, {"id": "f2", "type": "textarea", "label": "The thoughts that came with it:"}, {"id": "f3", "type": "textarea", "label": "The urges and the memories that showed up:"}, {"id": "f4", "type": "textarea", "label": "How the feeling seemed after looking at each piece on its own:"}]'::jsonb, array['core ACT', 'willingness', 'acceptance']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('postcard-from-a-valued-week', 'Postcard From a Valued Week', 'act'::resource_kind, 'A postcard the client writes from the end of a week lived by their values, describing what they did and noticed.', 'Use it to help a client picture a week shaped by values concretely enough to plan one piece of it.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to write as if it is Sunday night at the end of a week lived the way they want, addressing the card to you or to themselves. Keep it specific: what they did on Tuesday, who they called, what they said no to. Then pick one sentence from the postcard and make it true this week. The exercise turns abstract values into a scene with a date on it.', '[{"id": "f0", "type": "textarea", "label": "Dear ... (who the postcard is to):"}, {"id": "f1", "type": "textarea", "label": "What I did this week that I am glad about, in detail:"}, {"id": "f2", "type": "textarea", "label": "Something I said no to, and what it made room for:"}, {"id": "f3", "type": "textarea", "label": "A small moment I noticed and want to remember:"}, {"id": "f4", "type": "textarea", "label": "The one sentence from this postcard I will make true in the coming week:"}]'::jsonb, array['values', 'committed action', 'core ACT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('carrying-the-cards-pocket-practice', 'Carrying the Cards Pocket Practice', 'act'::resource_kind, 'A practice of writing difficult thoughts on index cards and carrying them in a pocket all week while doing what matters.', 'Use it to help a client learn that a hard thought can come along without stopping the day.', array['Adults', 'Teens']::text[], 'One week', 'In session, have the client write their three or four stickiest thoughts on separate cards, one per card, in their own words. Ask them to carry the cards in a pocket or bag for the week, taking one out to read whenever they notice the thought, then putting it back and continuing what they were doing. Debrief what it was like to have the thoughts physically along for the ride.', '[{"id": "f0", "type": "textarea", "label": "The thoughts I wrote on my cards:"}, {"id": "f1", "type": "textarea", "label": "Times this week I took a card out and read it:"}, {"id": "f2", "type": "textarea", "label": "What I was doing, and whether I kept doing it:"}, {"id": "f3", "type": "textarea", "label": "What changed about how the thoughts felt by the end of the week:"}, {"id": "f4", "type": "textarea", "label": "Which card I would keep carrying, and which I could leave at home:"}]'::jsonb, array['defusion', 'core ACT', 'willingness']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('taking-your-mind-for-a-walk-exercise', 'Taking Your Mind for a Walk Exercise', 'act'::resource_kind, 'A two-person walk in which one person plays the client''s mind, narrating nonstop, while the client chooses where to go.', 'Use it to let a client feel the difference between hearing the mind and obeying it.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Pair the client with you or a group partner. One person walks and chooses the route; the other walks a step behind as the mind, commenting, warning and advising without pause. Swap roles after five minutes. Debrief: what did the walker do with the chatter, and when did it pull them off course? Most clients notice how quickly the mind becomes background when they are busy choosing.', '[{"id": "f0", "type": "textarea", "label": "What my mind said when it was walking behind me:"}, {"id": "f1", "type": "textarea", "label": "Times I followed it, and times I kept my own route:"}, {"id": "f2", "type": "textarea", "label": "What it was like to play the mind for someone else:"}, {"id": "f3", "type": "textarea", "label": "A thought my real mind says that sounded a lot like the exercise:"}, {"id": "f4", "type": "textarea", "label": "What I will do with that thought next time it starts narrating:"}]'::jsonb, array['defusion', 'core ACT', 'metaphor']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('garden-metaphor-values-tending-page', 'Garden Metaphor Values Tending Page', 'act'::resource_kind, 'A page comparing values to plants in a garden that need tending whatever the weather, with weeds that return.', 'Use it to help a client see values as something to tend daily rather than a destination to reach.', array['Adults', 'Teens']::text[], '30 minutes', 'Draw a simple garden with a bed for each area of life the client cares about. Ask what each bed is growing, what it needs this week, and which beds have been left to go dry. Name the weeds: the thoughts and habits that keep coming back no matter how often they are pulled. The metaphor helps clients who treat values as a test they are failing; a garden is never finished and that is not a failure.', '[{"id": "f0", "type": "textarea", "label": "The beds in my garden and what each is growing:"}, {"id": "f1", "type": "textarea", "label": "Which beds I have been watering, and which have gone dry:"}, {"id": "f2", "type": "textarea", "label": "The weeds that keep coming back:"}, {"id": "f3", "type": "textarea", "label": "One bed I will tend this week, and what tending looks like:"}, {"id": "f4", "type": "textarea", "label": "What I notice about expecting the garden to be finished:"}]'::jsonb, array['values', 'metaphor', 'committed action']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-others-practice-sheet', 'Mindfulness of Others Practice Sheet', 'dbt'::resource_kind, 'A practice sheet for observing, describing and participating with another person without judgment or mind reading.', 'Use it to help a client bring the mindfulness skills to a conversation instead of to their own thoughts.', array['Adults', 'Teens']::text[], 'One week', 'Teach the three parts: observe the other person with curiosity, describe only what you saw and heard, and participate by giving them your full attention. Ask the client to pick one conversation a day to practice with. Most notice how quickly they drift into predicting, judging or planning their reply. Review the log in session and pick the part that was hardest to work on next.', '[{"id": "f0", "type": "textarea", "label": "The conversations I chose to practice with this week:"}, {"id": "f1", "type": "textarea", "label": "What I observed about the other person without adding meaning:"}, {"id": "f2", "type": "textarea", "label": "Judgments or guesses about their thoughts that I caught myself making:"}, {"id": "f3", "type": "textarea", "label": "Moments I was fully in the conversation rather than in my head:"}, {"id": "f4", "type": "textarea", "label": "The part (observe, describe, participate) that was hardest for me:"}]'::jsonb, array['core DBT', 'interpersonal effectiveness', 'mindfulness']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('dialectical-dilemmas-teen-and-parent-sheet', 'Dialectical Dilemmas Teen and Parent Sheet', 'dbt'::resource_kind, 'A sheet for a teen and parent to map where each has swung to an extreme and what the middle path would be.', 'Use it to help a teen and parent find the middle path on one recurring standoff.', array['Teens', 'Adults']::text[], 'Full session', 'Pick one standoff, such as curfew or phone use. Have the teen and parent each name the extreme they are accused of, too strict or too loose, too much control or too little, and the fear underneath it. Then build a middle path statement together that holds both truths. Keep the sheet to one issue; the skill is spotting the swing, not settling the whole relationship.', '[{"id": "f0", "type": "textarea", "label": "The standoff we are working on:"}, {"id": "f1", "type": "textarea", "label": "Teen: the extreme I think my parent swings to, and what I think they are afraid of:"}, {"id": "f2", "type": "textarea", "label": "Parent: the extreme I think my teen swings to, and what I think they are afraid of:"}, {"id": "f3", "type": "textarea", "label": "Both: what is true in each other''s position:"}, {"id": "f4", "type": "textarea", "label": "Our middle path statement for this issue, and one thing each of us will do differently:"}]'::jsonb, array['core DBT', 'family', 'middle path']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('ending-or-keeping-a-relationship-sheet', 'Ending or Keeping a Relationship Sheet', 'dbt'::resource_kind, 'A DBT interpersonal sheet for deciding in wise mind whether to end a relationship or work to repair it.', 'Use it to help a client weigh a strained relationship from wise mind rather than from the heat of the last argument.', array['Adults', 'Teens']::text[], 'Full session', 'Use this only when the client is not in emotion mind, and never right after a fight. Walk through what the relationship gives, what it costs, whether the problems have been addressed with skills already, and what the client''s values say about leaving or staying. If the decision is to end it, plan how to do so with self-respect. If it is to keep it, name the skills to try next.', '[{"id": "f0", "type": "textarea", "label": "What this relationship gives me, and what it costs me:"}, {"id": "f1", "type": "textarea", "label": "Skills I have already tried to improve it, and what happened:"}, {"id": "f2", "type": "textarea", "label": "What my values say about staying or leaving:"}, {"id": "f3", "type": "textarea", "label": "What my emotion mind says, and what my wise mind says:"}, {"id": "f4", "type": "textarea", "label": "My decision for now, and the next step that keeps my self-respect:"}]'::jsonb, array['core DBT', 'interpersonal effectiveness', 'decisions']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('contributing-acts-weekly-plan', 'Contributing Acts Weekly Plan', 'dbt'::resource_kind, 'A weekly plan of small acts of contributing, the C in ACCEPTS, used to shift attention out of a hard moment.', 'Use it to help a client build a ready list of ways to contribute when they need to step out of distress.', array['Adults', 'Teens']::text[], 'One week', 'Explain that contributing works by moving attention onto someone else for a while, not by fixing the client''s own problem. Build a list of acts that take under twenty minutes: a text to check on a friend, a chore for a housemate, a donation sorted, a note left for someone. Ask the client to use one when distress rises this week and note what happened to the distress while they were doing it.', '[{"id": "f0", "type": "textarea", "label": "Small ways I could contribute that take under twenty minutes:"}, {"id": "f1", "type": "textarea", "label": "The times this week I used one:"}, {"id": "f2", "type": "textarea", "label": "What my distress was doing before, during and after:"}, {"id": "f3", "type": "textarea", "label": "Which acts helped most, and which felt like a chore:"}, {"id": "f4", "type": "textarea", "label": "Three I will keep on my ready list:"}]'::jsonb, array['core DBT', 'distress tolerance', 'kindness']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('troubleshooting-emotion-regulation-skills-sheet', 'Troubleshooting Emotion Regulation Skills Sheet', 'dbt'::resource_kind, 'A sheet for finding why an emotion regulation skill did not work and what to try differently next time.', 'Use it to turn a skill that failed into information instead of a reason to quit.', array['Adults', 'Teens']::text[], '30 minutes', 'Take one recent moment when a skill did not help. Check in order: was the skill actually used as taught, was the emotion already too high for that skill, was there a vulnerability factor like no sleep, and was the client willing or just going through the motions. Each answer points to a different fix. End with the specific change for the next attempt rather than a new skill.', '[{"id": "f0", "type": "textarea", "label": "The skill I tried, and the situation:"}, {"id": "f1", "type": "textarea", "label": "Did I use it fully, the way it was taught? What did I skip?"}, {"id": "f2", "type": "textarea", "label": "How high was the emotion when I started, out of ten? Was that too high for this skill?"}, {"id": "f3", "type": "textarea", "label": "Vulnerability factors in play: sleep, food, illness, substances, stress:"}, {"id": "f4", "type": "textarea", "label": "The one change I will make the next time I use this skill:"}]'::jsonb, array['core DBT', 'emotion regulation', 'skills']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('sound-relationship-house-floor-check', 'Sound Relationship House Floor Check', 'couples'::resource_kind, 'A floor-by-floor check of the Gottman Sound Relationship House, with each partner rating the floors.', 'Use it to help partners see which parts of their relationship are solid and which need attention.', array['Couples']::text[], 'Full session', 'Describe the floors briefly: knowing each other''s worlds, fondness and admiration, turning toward, positive perspective, managing conflict, supporting dreams, shared meaning, with trust and commitment as the walls. Each partner rates each floor privately, then they compare. Disagreements about a rating are the richest material. Choose one floor to work on together before the next session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my rating for each floor, and the one I would most like to strengthen:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my rating for each floor, and the one I would most like to strengthen:"}, {"id": "f2", "type": "textarea", "label": "Floors where our ratings were far apart, and what each of us sees:"}, {"id": "f3", "type": "textarea", "label": "The floor we agree to work on first:"}, {"id": "f4", "type": "textarea", "label": "One thing each of us will do for that floor this week:"}]'::jsonb, array['Gottman', 'couples', 'connection']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('tone-of-voice-replay-sheet', 'Tone of Voice Replay Sheet', 'couples'::resource_kind, 'A sheet for replaying one sentence from an argument in the tone the speaker meant and the tone the listener heard.', 'Use it to show partners how tone, not words, carried the hurt in a recent exchange.', array['Couples']::text[], '30 minutes', 'Pick one sentence from a recent argument that each partner remembers differently. The speaker says it aloud in the tone they intended; the listener says it in the tone they heard. Both are usually right about something. Then the speaker tries the sentence a third way that would have landed. Keep it to one sentence per session so it stays an exercise and not a rerun of the fight.', '[{"id": "f0", "type": "textarea", "label": "The sentence we are replaying, in the exact words:"}, {"id": "f1", "type": "textarea", "label": "Speaker: what I meant, and the tone I thought I used:"}, {"id": "f2", "type": "textarea", "label": "Listener: what I heard, and the tone it carried for me:"}, {"id": "f3", "type": "textarea", "label": "The third version that would have landed better:"}, {"id": "f4", "type": "textarea", "label": "A signal we will use when tone is getting in the way:"}]'::jsonb, array['communication', 'couples', 'conflict']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('twenty-year-picture-interview-for-partners', 'Twenty-Year Picture Interview for Partners', 'couples'::resource_kind, 'Partners interview each other about the life they picture twenty years from now and look for the overlap.', 'Use it to help partners name the long view each carries and find the shared pieces to build toward.', array['Couples']::text[], 'Full session', 'Each partner interviews the other for ten minutes about an ordinary day twenty years out: where they wake up, who is around, what they do, what they have stopped doing. The interviewer only asks and writes. Then lay the two pictures side by side and mark overlaps and gaps. Gaps are not verdicts; they are the conversations the couple has been postponing.', '[{"id": "f0", "type": "textarea", "label": "Partner A''s picture of an ordinary day twenty years from now, as Partner B heard it:"}, {"id": "f1", "type": "textarea", "label": "Partner B''s picture of an ordinary day twenty years from now, as Partner A heard it:"}, {"id": "f2", "type": "textarea", "label": "Where the pictures overlap:"}, {"id": "f3", "type": "textarea", "label": "Where they differ, and which differences surprised us:"}, {"id": "f4", "type": "textarea", "label": "One piece of the shared picture we can start building now:"}]'::jsonb, array['couples', 'values', 'shared meaning']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('receiving-feedback-without-defending-practice', 'Receiving Feedback Without Defending Practice', 'couples'::resource_kind, 'A practice in which one partner gives one piece of feedback and the other listens, reflects and asks a question before replying.', 'Use it to help partners hear a complaint without launching a defense in the first ten seconds.', array['Couples']::text[], '30 minutes', 'The speaker offers one specific piece of feedback, kept to one sentence. The listener''s only jobs are to repeat the gist, ask one clarifying question and say what part they can own, without explaining or counter-complaining. Swap roles. Time the pause before the listener speaks; even three seconds changes the exchange. Debrief what each partner felt in the listening role.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the feedback I gave, in one sentence:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I heard, the question I asked and the part I can own:"}, {"id": "f2", "type": "textarea", "label": "Partner B: the feedback I gave, in one sentence:"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I heard, the question I asked and the part I can own:"}, {"id": "f4", "type": "textarea", "label": "What it was like to listen without defending, and where we each wanted to jump in:"}]'::jsonb, array['communication', 'couples', 'listening']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('celebrating-each-others-wins-sheet', 'Celebrating Each Other''s Wins Sheet', 'couples'::resource_kind, 'A sheet for noticing how each partner responds when the other shares good news, and practicing the response that builds closeness.', 'Use it to help partners respond to each other''s good news with interest instead of a nod or a worry.', array['Couples']::text[], '30 minutes', 'Describe the four ways people respond to good news: enthusiastic and curious, quiet approval, pointing out the downside, or changing the subject. Have each partner recall a recent win they shared and how the other responded. Then practice the enthusiastic version with a real piece of news from the week, asking two questions about it. Set a rule for the week: good news gets two questions.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a recent win I shared, and how my partner responded:"}, {"id": "f1", "type": "textarea", "label": "Partner B: a recent win I shared, and how my partner responded:"}, {"id": "f2", "type": "textarea", "label": "A piece of good news from this week, and the two questions my partner asked about it:"}, {"id": "f3", "type": "textarea", "label": "What it felt like to have a win met with curiosity:"}, {"id": "f4", "type": "textarea", "label": "Our rule for good news this week:"}]'::jsonb, array['connection', 'couples', 'appreciation']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('feelings-hopscotch-chalk-court', 'Feelings Hopscotch Chalk Court', 'kids'::resource_kind, 'A chalk hopscotch court where each square is a feeling and the child names a time they felt it as they hop.', 'Use it to help a child name feelings with their whole body moving, with a parent playing alongside.', array['Children']::text[], '20 minutes', 'Draw a hopscotch court outside or with tape indoors and write a feeling in each square: happy, mad, scared, proud, sad, silly, worried, calm. The child tosses a marker and hops to it, then tells a time they felt that feeling. The parent takes turns and shares their own examples, which gives the child permission to name the harder ones. Keep it light; the naming is the work.', '[{"id": "f0", "type": "textarea", "label": "The feelings we wrote in our squares:"}, {"id": "f1", "type": "textarea", "label": "A time I felt the feeling I landed on most:"}, {"id": "f2", "type": "textarea", "label": "A feeling my grown-up shared that surprised me:"}, {"id": "f3", "type": "textarea", "label": "The square I did not want to land on, and why:"}, {"id": "f4", "type": "textarea", "label": "What helps me when I feel that one:"}]'::jsonb, array['children', 'play', 'emotion identification']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('shadow-puppet-story-night', 'Shadow Puppet Story Night', 'kids'::resource_kind, 'A flashlight and a wall become a stage for a child to tell a story about a character who has a big feeling.', 'Use it to let a child tell a feeling story in the dark where it is easier, with a parent as audience.', array['Children']::text[], '30 minutes', 'Cut simple shapes from cardboard or use hands, dim the lights and give the child a flashlight. Ask them to tell a story about a character who has a big feeling and what the character does. The parent is the audience and asks what happens next rather than steering. Children often tell their own story through the puppet; let it stay the puppet''s story unless the child says otherwise.', '[{"id": "f0", "type": "textarea", "label": "The character in my story and the big feeling they had:"}, {"id": "f1", "type": "textarea", "label": "What happened to make them feel that way:"}, {"id": "f2", "type": "textarea", "label": "What the character did about it:"}, {"id": "f3", "type": "textarea", "label": "Who helped the character:"}, {"id": "f4", "type": "textarea", "label": "A story I might tell next time:"}]'::jsonb, array['children', 'play', 'externalizing']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('family-dinner-question-jar-craft', 'Family Dinner Question Jar Craft', 'kids'::resource_kind, 'A decorated jar of questions the family draws from at dinner, written by the child and the parent together.', 'Use it to give a family an easy way to talk at the table and the child a say in what gets asked.', array['Children']::text[], '30 minutes', 'The child decorates a jar while the parent cuts paper strips. Together they write questions, some silly and some real: best part of today, something that was hard, a time you helped someone. The child writes or dictates at least half. At dinner one person draws a question and everyone answers. Coach the parent to answer honestly and briefly, since the child learns what is safe to say from them.', '[{"id": "f0", "type": "textarea", "label": "Silly questions I put in the jar:"}, {"id": "f1", "type": "textarea", "label": "Real questions I put in the jar:"}, {"id": "f2", "type": "textarea", "label": "A question my grown-up wrote that I liked:"}, {"id": "f3", "type": "textarea", "label": "The question we drew tonight, and my answer:"}, {"id": "f4", "type": "textarea", "label": "What I learned about someone in my family from their answer:"}]'::jsonb, array['children', 'family', 'communication']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('flour-balloon-squeeze-ball-craft', 'Flour Balloon Squeeze Ball Craft', 'kids'::resource_kind, 'A homemade squeeze ball from a balloon and flour that the child makes, decorates and keeps for big feelings.', 'Use it to give a child a calming object they made themselves, with a plan for when to squeeze it.', array['Children']::text[], '30 minutes', 'The parent holds the balloon open while the child spoons in flour through a funnel, then ties it off and draws a face on it. Making it is messy on purpose; the mess is part of the fun. Then practice squeezing while taking slow breaths and decide where the ball will live. Agree with the parent on a cue, such as the child saying squeeze time, that means a break is needed.', '[{"id": "f0", "type": "textarea", "label": "The face or design I gave my squeeze ball:"}, {"id": "f1", "type": "textarea", "label": "Where my squeeze ball will live:"}, {"id": "f2", "type": "textarea", "label": "Feelings that mean it is squeeze time:"}, {"id": "f3", "type": "textarea", "label": "What I do while I squeeze it (breathe, count, walk):"}, {"id": "f4", "type": "textarea", "label": "Our family word for when I need a squeeze break:"}]'::jsonb, array['children', 'craft', 'self-soothing']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('three-panel-my-day-comic', 'Three Panel My Day Comic', 'kids'::resource_kind, 'A three-panel comic the child draws of their day: a beginning, a hard or funny middle and an ending.', 'Use it to help a child tell you about their day in pictures when words are hard to find.', array['Children']::text[], '20 minutes', 'Fold a page into three panels. Ask the child to draw how the day started, one thing that happened in the middle, and how it ended, with speech bubbles if they like. Ask about the middle panel last; children often save the real event for it. The parent can draw their own three panels alongside, which makes the sharing two-way. Keep the comics in a folder to look back on patterns.', '[{"id": "f0", "type": "textarea", "label": "Panel one: how my day started:"}, {"id": "f1", "type": "textarea", "label": "Panel two: something that happened in the middle:"}, {"id": "f2", "type": "textarea", "label": "Panel three: how my day ended:"}, {"id": "f3", "type": "textarea", "label": "A speech bubble I would add to the middle panel:"}, {"id": "f4", "type": "textarea", "label": "What my grown-up drew in their comic:"}]'::jsonb, array['children', 'drawing', 'communication']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('guess-the-coping-skill-twenty-questions', 'Guess the Coping Skill Twenty Questions', 'game'::resource_kind, 'A twenty questions game where one player picks a coping skill and the group narrows it down with yes-or-no questions.', 'Use it to get a group thinking about what coping skills have in common and when each one fits.', array['Groups', 'Teens']::text[], '20 minutes', 'One player secretly picks a skill from a list the group already knows. The others ask yes-or-no questions: does it use your body, can you do it at school, does it take under a minute. The group has twenty questions to guess. Rotate the picker. Debrief by sorting the skills that came up into categories the questions revealed, then ask each player which category they use least.', '[{"id": "f0", "type": "textarea", "label": "The skill I picked when it was my turn:"}, {"id": "f1", "type": "textarea", "label": "Questions that narrowed it down fastest:"}, {"id": "f2", "type": "textarea", "label": "Categories of skills we noticed (body, mind, people, place):"}, {"id": "f3", "type": "textarea", "label": "The category I use least, and a skill from it I could try:"}, {"id": "f4", "type": "textarea", "label": "A skill someone else picked that I had forgotten about:"}]'::jsonb, array['game', 'coping skills', 'group']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('balloon-keep-up-teamwork-game', 'Balloon Keep-Up Teamwork Game', 'game'::resource_kind, 'A group keeps several balloons off the floor while following rules that change each round, then debriefs how they coordinated.', 'Use it to let a group practice communication and frustration tolerance under playful pressure.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'Start with one balloon and the single rule that it cannot touch the floor. Each round add a balloon or a rule: no hands, no talking, everyone must touch it once. Play two minutes per round. Stop before it becomes chaotic. In the debrief, ask who took charge, who went quiet, how the group handled the no-talking round, and what the moment of frustration felt like in the body.', '[{"id": "f0", "type": "textarea", "label": "The rule that made it hardest for our group:"}, {"id": "f1", "type": "textarea", "label": "What I did when it got frustrating:"}, {"id": "f2", "type": "textarea", "label": "How we communicated when we could not talk:"}, {"id": "f3", "type": "textarea", "label": "Who stepped up, who stepped back, and where I fit:"}, {"id": "f4", "type": "textarea", "label": "One thing from the game that shows up in real teams I am part of:"}]'::jsonb, array['game', 'group', 'regulation']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('step-into-the-circle-if-game', 'Step Into the Circle If Game', 'game'::resource_kind, 'Players stand in a ring and step into the center when a statement is true for them, from silly to sincere.', 'Use it to help a group discover common ground quickly and lower the risk of sharing.', array['Groups', 'Teens']::text[], '20 minutes', 'Read statements starting with easy ones, such as I have a pet or I hate mornings, and move slowly toward ones that matter, such as I have had a week when getting out of bed was hard. Anyone who steps in looks around and notices who else did. No one has to step in, and no one explains. Debrief which statements surprised people and what it was like to be in the center with company.', '[{"id": "f0", "type": "textarea", "label": "A statement I stepped in for that I did not expect many others to:"}, {"id": "f1", "type": "textarea", "label": "A statement I chose not to step in for, even though it was true:"}, {"id": "f2", "type": "textarea", "label": "Who I noticed in the circle with me:"}, {"id": "f3", "type": "textarea", "label": "What it felt like to not be the only one:"}, {"id": "f4", "type": "textarea", "label": "A statement I would add to the list next time:"}]'::jsonb, array['game', 'group', 'connection']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('build-a-day-card-game', 'Build a Day Card Game', 'game'::resource_kind, 'Players draw activity cards and assemble a balanced day, trading cards to fit rest, work, people and movement into the hours.', 'Use it to help clients see what a steady day contains and what they tend to leave out.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Make a deck of cards with activities and the hours each takes: sleep, a meal, a walk, chores, a call with a friend, screen time, a hobby, nothing at all. Each player draws ten cards and must build a 24-hour day, trading with others to get what they need. When the days are built, each player reads theirs aloud. Debrief what everyone fought over, what got dropped first, and how the built day compares to a real one.', '[{"id": "f0", "type": "textarea", "label": "The day I built, hour by hour:"}, {"id": "f1", "type": "textarea", "label": "Cards I traded away, and why:"}, {"id": "f2", "type": "textarea", "label": "The card everyone seemed to want:"}, {"id": "f3", "type": "textarea", "label": "What my built day has that my real days usually skip:"}, {"id": "f4", "type": "textarea", "label": "One card I will put into tomorrow:"}]'::jsonb, array['game', 'routines', 'planning']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('red-flag-green-flag-card-game', 'Red Flag Green Flag Card Game', 'game'::resource_kind, 'Players sort relationship scenario cards into red flag, green flag or depends, then argue the depends pile.', 'Use it to get teens or a group talking about healthy and unhealthy relationship behaviors with examples.', array['Teens', 'Groups']::text[], '30 minutes', 'Write short scenarios on cards: a partner asks for your phone password, a friend cancels twice but calls to explain, someone keeps score of favors. Players take turns drawing a card and placing it in red, green or depends. Anyone may challenge a placement with a reason. The depends pile gets the longest discussion. Debrief with each player naming one green flag they want to be for others.', '[{"id": "f0", "type": "textarea", "label": "Cards I placed as red flags, and why:"}, {"id": "f1", "type": "textarea", "label": "Cards I placed as green flags, and why:"}, {"id": "f2", "type": "textarea", "label": "A card the group argued about, and what each side said:"}, {"id": "f3", "type": "textarea", "label": "A flag I have shown to someone else that I want to change:"}, {"id": "f4", "type": "textarea", "label": "One green flag I want to be known for:"}]'::jsonb, array['game', 'relationships', 'boundaries']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('crowded-place-exit-and-anchor-plan', 'Crowded Place Exit and Anchor Plan', 'worksheet'::resource_kind, 'A plan for one upcoming outing to a crowded place: where the exits are, what anchors the client, and who knows the plan.', 'Use it to help a client go somewhere crowded with a plan that keeps the choice to leave in their hands.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick one real outing in the next week. Map the exits and a quiet spot nearby, list two grounding anchors the client can use in a crowd, and decide what signal or message tells a support person they are leaving. Knowing the way out often makes staying possible. Stay with the present-day logistics; this plan does not ask about what happened, only about how to make Saturday workable.', '[{"id": "f0", "type": "textarea", "label": "The outing I am planning, and when:"}, {"id": "f1", "type": "textarea", "label": "Where the exits and a quiet spot are:"}, {"id": "f2", "type": "textarea", "label": "Two anchors I can use if the crowd gets to be too much (something to see, hold or count):"}, {"id": "f3", "type": "textarea", "label": "Who knows my plan, and the message I will send if I leave early:"}, {"id": "f4", "type": "textarea", "label": "What counts as success for this outing, even if I leave before the end:"}]'::jsonb, array['PTSD and trauma', 'safety', 'pacing']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('back-to-the-door-small-experiment-sheet', 'Back to the Door Small Experiment Sheet', 'cbt'::resource_kind, 'A small behavioral experiment in sitting with the door out of sight in a safe place for a set time, with predictions and results.', 'Use it to help a client test one present-day safety habit in a place they already know is safe.', array['Adults']::text[], 'One week', 'Choose a place the client already trusts, such as your office or a familiar cafe, and a short time, five minutes to start. Write the prediction of what will happen with the door behind them and how sure they are. Run it, then compare. Keep the client in charge of the length and the stopping point, and keep the experiment about today''s room, never about the past. Skip it if the client is not in a steady stretch.', '[{"id": "f0", "type": "textarea", "label": "The safe place and the time I will sit with the door out of sight:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen, and how sure I am out of ten:"}, {"id": "f2", "type": "textarea", "label": "What my body did during the minutes, from the start to the end:"}, {"id": "f3", "type": "textarea", "label": "What actually happened in the room:"}, {"id": "f4", "type": "textarea", "label": "What I want to try next time, or whether this length is enough for now:"}]'::jsonb, array['PTSD and trauma', 'behavioral experiment', 'safety behaviors']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('dropping-anchor-with-a-support-person-page', 'Dropping Anchor With a Support Person Page', 'act'::resource_kind, 'A dropping anchor practice done side by side with a trusted person who does the steps too.', 'Use it to help a client learn the anchor practice in company before using it alone.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach dropping anchor in session: feel the feet, press hands together, look around and name what is here, then notice the feeling is here too and so is the room. Then plan a practice at home with a trusted person who does the steps alongside, saying them aloud. Doing it with someone keeps the pace slow and makes the room feel more shared. This is a steadying practice; it does not revisit anything from the past.', '[{"id": "f0", "type": "textarea", "label": "The person I will practice with, and when:"}, {"id": "f1", "type": "textarea", "label": "The steps in my own words, so I can say them aloud:"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my feet, hands and the room:"}, {"id": "f3", "type": "textarea", "label": "What was different about doing it beside someone:"}, {"id": "f4", "type": "textarea", "label": "A moment this week when I might drop anchor on my own:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'core ACT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('glove-box-soothing-kit-card', 'Glove Box Soothing Kit Card', 'dbt'::resource_kind, 'A pocket card for building a small self-soothe kit that lives in the car for hard moments on the road or in parking lots.', 'Use it to help a client have soothing items within reach where reminders often catch them off guard.', array['Adults']::text[], '20 minutes', 'Many clients report that the car is where reminders land: a song, a smell, a stretch of road. Build a kit for the glove box with one item for each sense that fits in a small bag: a strong mint, a smooth stone, a photo, a scent, a short playlist. Add a card with the first two steps to take after pulling over safely. Review in a month which items were used and which can be swapped.', '[{"id": "f0", "type": "textarea", "label": "What I will put in the kit, one thing for each sense:"}, {"id": "f1", "type": "textarea", "label": "The first two steps I will take after pulling over:"}, {"id": "f2", "type": "textarea", "label": "A song or sound I can play that steadies me:"}, {"id": "f3", "type": "textarea", "label": "Who I can call or text from the car if I need a voice (988 by call or text is always an option):"}, {"id": "f4", "type": "textarea", "label": "What I used from the kit this month, and what I will swap:"}]'::jsonb, array['PTSD and trauma', 'self-soothing', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('gentle-wake-up-agreement-for-partners', 'Gentle Wake-Up Agreement for Partners', 'couples'::resource_kind, 'Partners agree on how to wake each other, how to approach when one is asleep, and what to do after a hard night.', 'Use it to help partners make waking and mornings predictable so neither starts the day startled.', array['Couples']::text[], '30 minutes', 'Ask each partner what wakes them badly: a touch, a sudden light, a voice too close. Agree on a wake-up routine both can live with: saying the name first from across the room, a lamp before the overhead light, no touching a sleeper from behind. Add what each wants after a bad night, whether a check-in or quiet. Keep it practical and present; nothing here needs the story of why.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what wakes me badly, and what wakes me gently:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what wakes me badly, and what wakes me gently:"}, {"id": "f2", "type": "textarea", "label": "Our wake-up routine, step by step:"}, {"id": "f3", "type": "textarea", "label": "What each of us wants the morning after a hard night:"}, {"id": "f4", "type": "textarea", "label": "How we will check whether this is working after two weeks:"}]'::jsonb, array['PTSD and trauma', 'couples', 'safety']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('twenty-four-hour-decision-delay-log', 'Twenty-Four Hour Decision Delay Log', 'worksheet'::resource_kind, 'A log of decisions the client wanted to make under anxiety, held for a day, with what they chose once calmer.', 'Use it to help a client separate anxiety-driven choices from considered ones by waiting one day.', array['Adults', 'Teens']::text[], 'Two weeks', 'Agree on which decisions count: canceling plans, sending a long message, quitting something, buying something to feel safer. When the urge comes, the client writes it down and waits twenty-four hours unless it is a true emergency. The next day they record what they chose. Review how often the delayed decision differed from the urgent one and what that says about anxiety as an advisor.', '[{"id": "f0", "type": "textarea", "label": "The decision I wanted to make right away, and the anxiety behind it:"}, {"id": "f1", "type": "textarea", "label": "What I did instead during the twenty-four hours:"}, {"id": "f2", "type": "textarea", "label": "What I decided once the day had passed:"}, {"id": "f3", "type": "textarea", "label": "How often the delayed decision matched the urgent one:"}, {"id": "f4", "type": "textarea", "label": "A kind of decision I will always give a day from now on:"}]'::jsonb, array['anxiety', 'decisions', 'self-monitoring']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('prediction-confidence-calibration-log', 'Prediction Confidence Calibration Log', 'cbt'::resource_kind, 'A log that pairs each anxious prediction with how sure the client was and whether it happened, to see how well confidence tracks reality.', 'Use it to show a client that feeling sure something bad will happen is not the same as it happening.', array['Adults', 'Teens']::text[], 'Two weeks', 'Each time the client notices an anxious prediction, they write it, rate how confident they are from 0 to 100, and set a date to check. When the date arrives they record the outcome. After two weeks, group the predictions by confidence level and count how many came true at each level. The gap between confidence and outcome is the finding; let the client state it in their own words.', '[{"id": "f0", "type": "textarea", "label": "The prediction, and the date I will know:"}, {"id": "f1", "type": "textarea", "label": "How sure I was, from 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "Looking at all my high-confidence predictions, how many came true:"}, {"id": "f4", "type": "textarea", "label": "What this tells me about trusting the feeling of certainty:"}]'::jsonb, array['anxiety', 'predictions', 'core CBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('unfinished-worry-willingness-practice', 'Unfinished Worry Willingness Practice', 'act'::resource_kind, 'A practice in deliberately leaving a worry unfinished, noticing the pull to resolve it and returning to the task at hand.', 'Use it to help a client tolerate an open worry without chasing it to a conclusion.', array['Adults', 'Teens']::text[], 'One week', 'Explain that worry promises to finish if given a little more time and rarely does. Ask the client to pick one worry a day, notice it, say to themselves this one stays open, and return to what they were doing. Rate the pull to keep thinking before and after. Most find the pull drops within minutes when they stop feeding it. Debrief what they did with the time they got back.', '[{"id": "f0", "type": "textarea", "label": "The worry I left unfinished today:"}, {"id": "f1", "type": "textarea", "label": "How strong the pull to finish it was, before and ten minutes later:"}, {"id": "f2", "type": "textarea", "label": "What I went back to doing:"}, {"id": "f3", "type": "textarea", "label": "What my mind said about leaving it open:"}, {"id": "f4", "type": "textarea", "label": "What I did with the time I got back this week:"}]'::jsonb, array['anxiety', 'willingness', 'worry']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('contributing-skill-for-anxious-evenings-card', 'Contributing Skill for Anxious Evenings Card', 'dbt'::resource_kind, 'A card of small ways to contribute to someone else during the evening hours when anxiety tends to rise.', 'Use it to help a client shift attention outward in the evening with one small act for another person.', array['Adults', 'Teens']::text[], 'One week', 'Map the evening hours when the client''s anxiety climbs. Build a list of ten-minute contributions that fit those hours: a message to someone having a hard week, a small chore for a housemate, a review for a local business, a card written and stamped. The client picks one when they notice the climb. Note that this is a distress tolerance skill for the moment, not a way to avoid the worry forever.', '[{"id": "f0", "type": "textarea", "label": "The evening hours when my anxiety usually climbs:"}, {"id": "f1", "type": "textarea", "label": "Ten-minute ways I could contribute during those hours:"}, {"id": "f2", "type": "textarea", "label": "The evenings I used one this week, and which one:"}, {"id": "f3", "type": "textarea", "label": "What my anxiety did while I was doing it:"}, {"id": "f4", "type": "textarea", "label": "Two contributions I will keep on the card:"}]'::jsonb, array['anxiety', 'distress tolerance', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('brave-spy-mission-cards-craft', 'Brave Spy Mission Cards Craft', 'kids'::resource_kind, 'The child makes secret-agent mission cards, each with one small brave task, and completes a mission a day with a parent as handler.', 'Use it to turn small steps toward a worry into a spy game the child controls.', array['Children']::text[], 'One week', 'The child decorates index cards as top-secret missions. Together write small brave tasks that match their worry: order their own food, sleep with one light off, say hi to a neighbor. The parent is the handler who hands over one mission a day and takes the report afterward. Missions are chosen by the child; the parent never adds a harder one without asking. Celebrate reports, not perfect missions.', '[{"id": "f0", "type": "textarea", "label": "My spy name and my handler''s name:"}, {"id": "f1", "type": "textarea", "label": "The missions I wrote on my cards:"}, {"id": "f2", "type": "textarea", "label": "Today''s mission and my report on how it went:"}, {"id": "f3", "type": "textarea", "label": "What I was worried would happen, and what really happened:"}, {"id": "f4", "type": "textarea", "label": "The next mission I am ready to accept:"}]'::jsonb, array['anxiety', 'children', 'play']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('daylight-minutes-log', 'Daylight Minutes Log', 'worksheet'::resource_kind, 'A simple log of minutes spent in daylight each day beside the client''s mood and energy ratings.', 'Use it to help a client see whether time outdoors in daylight travels with their mood.', array['Adults', 'Teens']::text[], 'Two weeks', 'Ask the client to note the minutes they spent outside in daylight each day, even standing on a step, and rate mood and energy that evening. Do not set a target in the first week; the log is for looking. In the second week, if they see a link, agree on a small daylight habit tied to something they already do, like coffee on the porch. Keep expectations modest and the step small.', '[{"id": "f0", "type": "textarea", "label": "Minutes in daylight today, and roughly when:"}, {"id": "f1", "type": "textarea", "label": "Mood and energy this evening, out of ten:"}, {"id": "f2", "type": "textarea", "label": "What I notice when I look at the two weeks side by side:"}, {"id": "f3", "type": "textarea", "label": "A daylight habit I could attach to something I already do:"}, {"id": "f4", "type": "textarea", "label": "What got in the way on the days with no daylight at all:"}]'::jsonb, array['depression', 'self-monitoring', 'routines']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('doing-nothing-versus-resting-sort-sheet', 'Doing Nothing Versus Resting Sort Sheet', 'cbt'::resource_kind, 'A sheet for sorting the client''s downtime into rest that refills them and shutdown that leaves them emptier.', 'Use it to help a client tell real rest from collapse and plan more of the kind that restores.', array['Adults', 'Teens']::text[], '30 minutes', 'List the client''s downtime from the past week: scrolling in bed, lying on the couch, a bath, a nap, staring at the ceiling. For each, ask how they felt an hour afterward. Sort them into refilling rest and emptying shutdown. Low mood often tells the client all downtime is the same; the afterward feeling says otherwise. Plan one refilling rest for each day this week and treat it as a task that counts.', '[{"id": "f0", "type": "textarea", "label": "My downtime this week, item by item:"}, {"id": "f1", "type": "textarea", "label": "How I felt an hour after each one:"}, {"id": "f2", "type": "textarea", "label": "Which items refilled me, and which left me emptier:"}, {"id": "f3", "type": "textarea", "label": "One refilling rest I will schedule each day:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself when shutdown looks like the easier option:"}]'::jsonb, array['depression', 'behavioral activation', 'energy']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('heavy-blanket-metaphor-page', 'Heavy Blanket Metaphor Page', 'act'::resource_kind, 'A page comparing low mood to a heavy blanket the client can move under, slowly, rather than wait to have lifted.', 'Use it to help a client take valued steps while the heaviness is still present.', array['Adults', 'Teens']::text[], '20 minutes', 'Describe low mood as a heavy blanket draped over everything: it slows movement and muffles sound, but the person under it can still move, slowly and with effort. Ask the client what they would do today if the blanket were gone, then what the slowest version of that looks like with the blanket still on. Celebrate movement under weight. Pair with a safety check if hopelessness is high.', '[{"id": "f0", "type": "textarea", "label": "What the blanket feels like today, out of ten:"}, {"id": "f1", "type": "textarea", "label": "What I would do today if it were gone:"}, {"id": "f2", "type": "textarea", "label": "The slowest version of that I could do with the blanket still on:"}, {"id": "f3", "type": "textarea", "label": "What I did, and how it felt to move under the weight:"}, {"id": "f4", "type": "textarea", "label": "If the weight ever comes with thoughts of not wanting to be here, who I will tell (988 by call or text is one option):"}]'::jsonb, array['depression', 'metaphor', 'committed action']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('mindful-of-the-good-moment-card', 'Mindful of the Good Moment Card', 'dbt'::resource_kind, 'A card for staying fully in a pleasant moment when it happens, noticing the pull toward worry or what comes next.', 'Use it to help a client get the full benefit of positive moments instead of thinking past them.', array['Adults', 'Teens']::text[], 'One week', 'Teach the three parts: notice the pleasant moment, put attention fully on it, and when the mind drifts to worry or to when it will end, gently bring it back. Ask the client to catch one such moment a day, even a warm drink or a song. The mood often skips pleasant events because attention never lands on them. Review what pulled attention away most and whether the moments felt longer by the end of the week.', '[{"id": "f0", "type": "textarea", "label": "The pleasant moment I caught today:"}, {"id": "f1", "type": "textarea", "label": "What my mind tried to pull me toward instead:"}, {"id": "f2", "type": "textarea", "label": "What I noticed when I brought attention back:"}, {"id": "f3", "type": "textarea", "label": "Whether the moment felt longer or fuller than usual:"}, {"id": "f4", "type": "textarea", "label": "A moment tomorrow I can plan to stay in:"}]'::jsonb, array['depression', 'emotion regulation', 'mindfulness']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('ten-second-starts-card-game', 'Ten Second Starts Card Game', 'game'::resource_kind, 'Players draw cards naming tasks that can be started in ten seconds and race to begin them, scoring for starts rather than finishes.', 'Use it to help a group feel how small a real start can be on days when everything looks too big.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Make cards with tasks that can begin in ten seconds: put one dish in the sink, open the email, put on one shoe, write one word. Players draw a card, the timer runs ten seconds, and a point is scored for any real start. Finishing earns nothing extra. Play five rounds. Debrief what the body felt like at the ten-second mark and which real-life tasks could be cut down to a ten-second start.', '[{"id": "f0", "type": "textarea", "label": "The cards I drew and whether I started each in ten seconds:"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body right before I started:"}, {"id": "f2", "type": "textarea", "label": "How it felt to score for starting rather than finishing:"}, {"id": "f3", "type": "textarea", "label": "A real task of mine that could have a ten-second start:"}, {"id": "f4", "type": "textarea", "label": "When I will try that start this week:"}]'::jsonb, array['depression', 'game', 'task initiation']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('out-of-sight-audit-sheet', 'Out of Sight Audit Sheet', 'worksheet'::resource_kind, 'An audit of the things the client forgets because they are stored out of view, with a visible home for each.', 'Use it to help a client set up visible storage for the items and tasks they lose track of.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask what the client has forgotten, lost or let expire in the past month: medication, bills, laundry in the washer, food in a drawer. For each, find where it was and whether it was visible. Most were in a closed cupboard or a drawer. Choose one visible home for each: a clear bin, a hook by the door, an open shelf. Pick the two with the biggest payoff and set them up this week.', '[{"id": "f0", "type": "textarea", "label": "Things I forgot or lost this month, and where they were:"}, {"id": "f1", "type": "textarea", "label": "Which of them were out of sight when I forgot them:"}, {"id": "f2", "type": "textarea", "label": "A visible home for each one:"}, {"id": "f3", "type": "textarea", "label": "The two I will set up first, and when:"}, {"id": "f4", "type": "textarea", "label": "What changed after a week with them in view:"}]'::jsonb, array['ADHD', 'executive function', 'routines']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('waiting-mode-thought-record', 'Waiting Mode Thought Record', 'cbt'::resource_kind, 'A thought record for the hours before an appointment when the client feels unable to start anything else.', 'Use it to help a client test the thought that nothing can be done until the appointment is over.', array['Adults', 'Teens']::text[], '20 minutes', 'Name waiting mode: the stretch before a scheduled event when the client paces or scrolls because starting anything feels impossible. Catch the thought, often I will lose track of time or I cannot get into anything in two hours. Test it with a timer and a task that fits the window, and record what actually happened. Build a short list of waiting-mode tasks with a hard stop built in.', '[{"id": "f0", "type": "textarea", "label": "The appointment, and how long the wait before it was:"}, {"id": "f1", "type": "textarea", "label": "The thought that kept me from starting anything:"}, {"id": "f2", "type": "textarea", "label": "The timed task I tried in the window, and the alarm I set:"}, {"id": "f3", "type": "textarea", "label": "What actually happened, including whether I was late:"}, {"id": "f4", "type": "textarea", "label": "My list of tasks that fit a waiting window:"}]'::jsonb, array['ADHD', 'thinking traps', 'time blindness']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('shiny-new-idea-noticing-page', 'Shiny New Idea Noticing Page', 'act'::resource_kind, 'A defusion page for the rush of a new project idea, noticing the pull before deciding whether to act.', 'Use it to help a client enjoy a new idea without abandoning the current one on the spot.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to describe the feeling of a shiny new idea: the energy, the certainty, the urge to buy supplies tonight. Teach them to label it, I am having the shiny new idea feeling, and write the idea on a parking page with a date. The rule is to revisit in a week before acting. Many ideas lose their shine; the ones that keep it earn a plan. Review the page in session and look at which ideas survived.', '[{"id": "f0", "type": "textarea", "label": "The idea that arrived this week, and how it felt in my body:"}, {"id": "f1", "type": "textarea", "label": "What I wanted to do about it that same night:"}, {"id": "f2", "type": "textarea", "label": "What I wrote on the parking page instead:"}, {"id": "f3", "type": "textarea", "label": "A week later: does it still have its shine?"}, {"id": "f4", "type": "textarea", "label": "What I notice about the pattern across the ideas on my page:"}]'::jsonb, array['ADHD', 'defusion', 'values']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-boredom-practice-log', 'Mindfulness of Boredom Practice Log', 'dbt'::resource_kind, 'A log of short practices in sitting with boredom and describing it, instead of reaching for a screen or a snack.', 'Use it to help a client observe boredom as a feeling that rises and passes, so it steers them less.', array['Adults', 'Teens']::text[], 'One week', 'Set up a daily two-minute practice: when boredom shows up, the client sets a timer and observes it. Where is it in the body, what does the mind say, what does it want them to do. They describe it in plain words and let the timer end before deciding what to do next. Boredom drives a lot of impulsive switching; a two-minute pause often changes what comes after it.', '[{"id": "f0", "type": "textarea", "label": "When the boredom showed up, and what I was doing:"}, {"id": "f1", "type": "textarea", "label": "Where I felt it in my body, and what it felt like:"}, {"id": "f2", "type": "textarea", "label": "What my mind said, and what it wanted me to do:"}, {"id": "f3", "type": "textarea", "label": "What I chose to do when the two minutes ended:"}, {"id": "f4", "type": "textarea", "label": "Whether the boredom changed during the two minutes:"}]'::jsonb, array['ADHD', 'mindfulness', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('lost-items-blame-free-agreement-for-partners', 'Lost Items Blame-Free Agreement for Partners', 'couples'::resource_kind, 'Partners agree on what happens when something is lost: who looks, what gets said and what does not.', 'Use it to take the blame out of the lost-keys moment so it stops becoming a fight.', array['Couples']::text[], '30 minutes', 'Ask each partner to describe the last lost-item moment from their side: what was said, what it felt like. Then write an agreement for next time: a search routine, a sentence each will not say, a landing spot by the door, and how long to look before changing the plan. The partner who loses things is usually already flooded with shame; the agreement protects both from the spiral.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the last time something was lost, what I said and felt:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the last time something was lost, what I said and felt:"}, {"id": "f2", "type": "textarea", "label": "Our search routine, in order:"}, {"id": "f3", "type": "textarea", "label": "One sentence each of us agrees not to say:"}, {"id": "f4", "type": "textarea", "label": "The landing spots we will set up, and how long we look before changing plans:"}]'::jsonb, array['ADHD', 'couples', 'communication']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('boredom-plan-for-early-recovery-sheet', 'Boredom Plan for Early Recovery Sheet', 'worksheet'::resource_kind, 'A plan for the empty hours that open up when substance use stops, with activities sorted by energy and time of day.', 'Use it to help a client fill the hours that used to be taken up by substance use before urges fill them.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask when substance use took up the client''s time: which evenings, which afternoons, before or after what. Those hours are now open and boredom there is a risk. Build a menu of things to do in those exact windows, sorted by how much energy they take, with at least two that involve another person. Review which windows were hardest and move the easiest activities into them.', '[{"id": "f0", "type": "textarea", "label": "The hours of the week that used to go to substance use:"}, {"id": "f1", "type": "textarea", "label": "Low-energy things I can do in those hours:"}, {"id": "f2", "type": "textarea", "label": "Higher-energy things I can do in those hours:"}, {"id": "f3", "type": "textarea", "label": "Two of these that involve another person:"}, {"id": "f4", "type": "textarea", "label": "The windows that were hardest this week, and what I will move into them:"}]'::jsonb, array['addiction', 'planning', 'urges']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('seemingly-unimportant-decisions-log', 'Seemingly Unimportant Decisions Log', 'cbt'::resource_kind, 'A log of the small, innocent-looking decisions that moved the client closer to a high-risk situation.', 'Use it to help a client spot the chain of small choices that leads toward substance use before the last link.', array['Adults', 'Teens']::text[], 'Two weeks', 'Introduce the idea that a return to use rarely starts at the moment of use; it starts hours or days earlier with a small decision that seemed to have nothing to do with it, such as taking the old route home or keeping a number in the phone. Have the client log the small decisions around any close call. Then mark the earliest point in each chain where a different choice was available.', '[{"id": "f0", "type": "textarea", "label": "The close call or risky moment, and when it happened:"}, {"id": "f1", "type": "textarea", "label": "The small decisions in the hours or days before it, in order:"}, {"id": "f2", "type": "textarea", "label": "Which of them seemed harmless at the time:"}, {"id": "f3", "type": "textarea", "label": "The earliest link where I could have chosen differently:"}, {"id": "f4", "type": "textarea", "label": "A small decision I will make differently this week:"}]'::jsonb, array['addiction', 'relapse prevention', 'core CBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('shame-and-values-after-a-slip-page', 'Shame and Values After a Slip Page', 'act'::resource_kind, 'A page for carrying shame after a slip while taking the next valued step, instead of waiting for the shame to pass.', 'Use it to help a client move after a slip without letting shame decide the next week.', array['Adults', 'Teens']::text[], '30 minutes', 'After a slip, shame arrives with a story that the client is back at the start. Ask them to describe the shame as a feeling in the body and name the story the mind tells. Then look at the values that made them want to change in the first place; those have not gone anywhere. Choose one small step toward those values for today, taken with the shame along rather than after it leaves.', '[{"id": "f0", "type": "textarea", "label": "What happened, in one sentence, without the lecture:"}, {"id": "f1", "type": "textarea", "label": "Where shame sits in my body, and the story my mind is telling:"}, {"id": "f2", "type": "textarea", "label": "The values that made me want this change in the first place:"}, {"id": "f3", "type": "textarea", "label": "One small step toward them I can take today, with the shame still here:"}, {"id": "f4", "type": "textarea", "label": "Who I will tell about the slip, and when:"}]'::jsonb, array['addiction', 'self-compassion', 'values']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('clear-mind-check-in-card', 'Clear Mind Check-In Card', 'dbt'::resource_kind, 'A card for noticing which mind is talking: the one that says risk is gone, the one that lives in fear, or the clear mind between them.', 'Use it to help a client catch the overconfident and the fearful mind states that both make substance use more likely.', array['Adults', 'Teens']::text[], 'One week', 'Describe the three states from DBT work on substance use: the mind that says I have this handled and stops watching for risk, the mind that is so afraid of a slip that it cannot act, and the clear mind that stays aware of risk while living a life. Ask the client to check in three times a day and name which mind is talking. Clear mind is the target, and noticing is most of the skill.', '[{"id": "f0", "type": "textarea", "label": "Morning check-in: which mind is talking, and what it is saying:"}, {"id": "f1", "type": "textarea", "label": "Midday check-in: which mind, and what it is saying:"}, {"id": "f2", "type": "textarea", "label": "Evening check-in: which mind, and what it is saying:"}, {"id": "f3", "type": "textarea", "label": "What clear mind sounded like today, if I found it:"}, {"id": "f4", "type": "textarea", "label": "A situation this week where the overconfident mind showed up:"}]'::jsonb, array['addiction', 'core DBT', 'urges']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('grown-up-problems-are-not-kid-jobs-poster', 'Grown-Up Problems Are Not Kid Jobs Poster', 'kids'::resource_kind, 'A poster the child makes about which problems belong to grown-ups, with the helpers they can go to.', 'Use it to help a child living with a parent''s substance use set down jobs that are not theirs.', array['Children']::text[], '30 minutes', 'Help the child draw two columns: kid jobs, like school and play and telling a grown-up when something is wrong, and grown-up jobs, like paying bills and getting better. Let the child decide which column things go in and gently correct when they claim a grown-up job. Add a strip of safe helpers along the bottom. If a child discloses they are unsafe or unsupervised, follow your reporting duties; a parent or other safe adult should be part of the plan.', '[{"id": "f0", "type": "textarea", "label": "Jobs that are mine as a kid:"}, {"id": "f1", "type": "textarea", "label": "Jobs that belong to grown-ups:"}, {"id": "f2", "type": "textarea", "label": "Something I have been trying to fix that is really a grown-up job:"}, {"id": "f3", "type": "textarea", "label": "Grown-ups I can go to when I am worried:"}, {"id": "f4", "type": "textarea", "label": "Where my poster will hang:"}]'::jsonb, array['addiction', 'children', 'family']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('hungry-tired-rushed-anger-fuel-sheet', 'Hungry Tired Rushed Anger Fuel Sheet', 'worksheet'::resource_kind, 'A sheet that checks three fuels behind recent anger flares: hunger, tiredness and being rushed.', 'Use it to help a client see how often a flare had a physical fuel behind it and plan for the fuels.', array['Adults', 'Teens']::text[], 'One week', 'For each flare in the week, the client notes the time, whether they had eaten in the past four hours, how they had slept, and whether they were running late. Over a week a pattern usually shows, often late afternoon on short sleep. The plan is practical: a snack in the bag, a buffer before the hardest transition. This is about fuel, not excuses; the choice in the moment is still theirs.', '[{"id": "f0", "type": "textarea", "label": "Each flare this week: when, and what set it off:"}, {"id": "f1", "type": "textarea", "label": "Hungry? When I had last eaten:"}, {"id": "f2", "type": "textarea", "label": "Tired? How I had slept the night before:"}, {"id": "f3", "type": "textarea", "label": "Rushed? Whether I was running late or squeezed:"}, {"id": "f4", "type": "textarea", "label": "The fuel that showed up most, and one way I will plan for it:"}]'::jsonb, array['anger management', 'self-monitoring', 'triggers']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('punishment-urge-versus-problem-solve-sheet', 'Punishment Urge Versus Problem Solve Sheet', 'cbt'::resource_kind, 'A sheet for separating the urge to make someone pay from the problem that actually needs solving.', 'Use it to help a client notice when anger has switched from fixing the problem to punishing the person.', array['Adults', 'Teens']::text[], '20 minutes', 'Take one recent conflict. Ask what the problem was and what the client wanted the other person to feel. If the answer to the second question is sorry or small, the anger has moved to punishment, which rarely solves the problem and often creates a new one. Write what solving the problem would actually require and what the punishing move would have cost. Then script the problem-solving version.', '[{"id": "f0", "type": "textarea", "label": "The conflict, and the problem underneath it:"}, {"id": "f1", "type": "textarea", "label": "What I wanted the other person to feel:"}, {"id": "f2", "type": "textarea", "label": "The punishing move I made or wanted to make, and what it cost or would cost:"}, {"id": "f3", "type": "textarea", "label": "What actually solving the problem would require:"}, {"id": "f4", "type": "textarea", "label": "The sentence I could have said that aimed at the problem:"}]'::jsonb, array['anger management', 'core CBT', 'problem solving']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('anger-expiration-date-reflection-page', 'Anger Expiration Date Reflection Page', 'act'::resource_kind, 'A reflection on how long the client wants to carry a particular grievance and what carrying it costs each week.', 'Use it to help a client decide, by their values, how long a grudge gets to ride along.', array['Adults']::text[], '30 minutes', 'Pick one grievance the client has carried for a while. Ask how often it comes up, what it costs in sleep and attention, and what it protects. Then ask what expiration date they would choose if they could set one, and what they would be doing with the attention after that date. The exercise does not demand forgiveness; it asks the client to choose how much of their life the grievance gets.', '[{"id": "f0", "type": "textarea", "label": "The grievance I am carrying, and how long I have carried it:"}, {"id": "f1", "type": "textarea", "label": "How often it comes up, and what it costs me each week:"}, {"id": "f2", "type": "textarea", "label": "What it is protecting or proving:"}, {"id": "f3", "type": "textarea", "label": "The expiration date I would set, if I could:"}, {"id": "f4", "type": "textarea", "label": "What I would do with the attention after that date:"}]'::jsonb, array['anger management', 'values', 'acceptance']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('describe-not-judge-anger-replay-sheet', 'Describe Not Judge Anger Replay Sheet', 'dbt'::resource_kind, 'A sheet for replaying an angry moment using only observable facts, with every judgment word circled and replaced.', 'Use it to help a client retell a conflict without the judgments that keep the anger lit.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client write the angry moment as they would normally tell it. Then go through and circle every judgment: rude, disrespectful, selfish, on purpose. Replace each with what was seen or heard: he looked at his phone while I was talking; she said no in a flat voice. Rate the anger after each version. Judgments feel like facts and refuel anger; the describe skill lets the facts stand on their own.', '[{"id": "f0", "type": "textarea", "label": "The moment as I would normally tell it:"}, {"id": "f1", "type": "textarea", "label": "The judgment words I circled:"}, {"id": "f2", "type": "textarea", "label": "The same moment described in facts only, what I saw and heard:"}, {"id": "f3", "type": "textarea", "label": "My anger rating after each version, out of ten:"}, {"id": "f4", "type": "textarea", "label": "The judgment I use most often, and what I will say instead:"}]'::jsonb, array['anger management', 'mindfulness', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('slow-motion-argument-replay-game', 'Slow Motion Argument Replay Game', 'game'::resource_kind, 'Players reenact a scripted argument in slow motion, freezing at any point to name the body cue and choose a different move.', 'Use it to let a group see the choice points inside an argument that normally fly by.', array['Groups', 'Teens']::text[], '30 minutes', 'Give two players a short scripted argument. They act it at half speed. Any audience member can call freeze; the actors hold still while the caller names what the character''s body is probably doing and what else the character could say. The actors then continue with the new line. Rotate roles. Debrief which freeze points mattered most and what cue each player would watch for in themselves.', '[{"id": "f0", "type": "textarea", "label": "The scripted argument we used:"}, {"id": "f1", "type": "textarea", "label": "The freeze points the group called, and what was happening at each:"}, {"id": "f2", "type": "textarea", "label": "The body cue I noticed in the actors that I have felt myself:"}, {"id": "f3", "type": "textarea", "label": "The new line that changed where the argument went:"}, {"id": "f4", "type": "textarea", "label": "The cue I will watch for in my own arguments this week:"}]'::jsonb, array['anger management', 'game', 'de-escalation']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('not-just-right-feeling-log', 'Not Just Right Feeling Log', 'worksheet'::resource_kind, 'A log of moments when something felt not quite right and the urge to fix, redo or even it out, with what the client did.', 'Use it to help a client see the not-just-right feeling as a pattern with a shape rather than a command.', array['Adults', 'Teens']::text[], 'One week', 'Many clients describe a sense of incompleteness rather than a feared outcome: a sentence that needs rereading, objects that need lining up, a touch that needs evening out. Log each moment: what felt off, the urge, how strong it was, and whether they acted. Over a week, look at how the feeling moved when it was not acted on. This log informs the work; it is not itself a change plan.', '[{"id": "f0", "type": "textarea", "label": "What felt not quite right, and when:"}, {"id": "f1", "type": "textarea", "label": "The urge that came with it (redo, even out, reread, touch):"}, {"id": "f2", "type": "textarea", "label": "How strong the urge was, out of ten:"}, {"id": "f3", "type": "textarea", "label": "Whether I acted on it, and what the feeling did either way:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the pattern across the week:"}]'::jsonb, array['OCD', 'self-monitoring', 'intrusive thoughts']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('feared-story-exposure-script-planner', 'Feared Story Exposure Script Planner', 'cbt'::resource_kind, 'A planner for writing and recording a short script of a feared outcome to listen to repeatedly, built with the clinician.', 'Use it to plan an imaginal exposure script with a client who has rituals around a thought that cannot be tested in real life.', array['Adults']::text[], 'Full session', 'This belongs in session with a client who already understands exposure with response prevention. Choose the feared story, agree the level of detail, and write it in present tense in the client''s words. Plan how they will listen daily, what rituals they will hold off, and how they will rate distress across the week. Review the recordings together and adjust the script before raising the intensity.', '[{"id": "f0", "type": "textarea", "label": "The feared story we chose, in one line:"}, {"id": "f1", "type": "textarea", "label": "The script in present tense, in my words (written in session):"}, {"id": "f2", "type": "textarea", "label": "The rituals I will hold off while listening, and for how long:"}, {"id": "f3", "type": "textarea", "label": "My distress ratings at the start, middle and end of each listen:"}, {"id": "f4", "type": "textarea", "label": "What changed across the week, and what we will adjust:"}]'::jsonb, array['OCD', 'exposure', 'core CBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('mental-checking-as-background-chatter-practice', 'Mental Checking as Background Chatter Practice', 'act'::resource_kind, 'A defusion practice for mental reviewing and checking, treating it as chatter from the next room rather than a task to finish.', 'Use it to help a client let mental checking run in the background without joining in.', array['Adults', 'Teens']::text[], 'One week', 'Mental checking is quieter than visible rituals and clients often feel they must answer it. Teach them to notice the review starting, label it, the checking chatter is on, and picture it as a radio in the next room: audible, not in charge. They return to the task in front of them without turning the radio off. Log the episodes and what they went back to doing. The aim is less joining in, not silence.', '[{"id": "f0", "type": "textarea", "label": "When the checking chatter started, and what it was reviewing:"}, {"id": "f1", "type": "textarea", "label": "How I labeled it:"}, {"id": "f2", "type": "textarea", "label": "What I went back to doing while it ran:"}, {"id": "f3", "type": "textarea", "label": "How long it took to fade when I did not join in:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the difference between hearing it and answering it:"}]'::jsonb, array['OCD', 'defusion', 'intrusive thoughts']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('half-smile-for-not-just-right-moments-card', 'Half Smile for Not Just Right Moments Card', 'dbt'::resource_kind, 'A card pairing the half smile and willing hands posture with the moments when something feels incomplete.', 'Use it to give a client a body-based way to stay in an unfinished moment without fixing it.', array['Adults', 'Teens']::text[], 'One week', 'Teach the half smile and willing hands in session: a slight lift at the corners of the mouth, hands open and palms up or resting. Then ask the client to use the posture the next time something feels not quite right and they are holding off the fix. The body tells the mind the moment is survivable. Rate the urge before and after holding the posture for one minute.', '[{"id": "f0", "type": "textarea", "label": "The not-just-right moment I used the card for:"}, {"id": "f1", "type": "textarea", "label": "The urge rating before I took the posture:"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my face and hands during the minute:"}, {"id": "f3", "type": "textarea", "label": "The urge rating after:"}, {"id": "f4", "type": "textarea", "label": "Whether I fixed the thing afterward, and how I feel about either choice:"}]'::jsonb, array['OCD', 'core DBT', 'distress tolerance']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('couple-values-beyond-the-rituals-page', 'Couple Values Beyond the Rituals Page', 'couples'::resource_kind, 'Partners name what they want their shared life to be about and what the rituals have been taking from it.', 'Use it to help partners anchor the hard work around rituals in the life they both want.', array['Couples']::text[], 'Full session', 'Each partner names three things they want the relationship to be about, such as travel, hosting friends, ease at home. Then they list, without blame, which of these the rituals and the accommodation around them have crowded out. Finally they choose one small shared activity that moves toward a value this week, even if a ritual comes along. Keep the conversation on the life, not on who causes what.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three things I want our life together to be about:"}, {"id": "f1", "type": "textarea", "label": "Partner B: three things I want our life together to be about:"}, {"id": "f2", "type": "textarea", "label": "Which of these the rituals and the working around them have crowded out:"}, {"id": "f3", "type": "textarea", "label": "One shared activity this week that moves toward a value, even if a ritual comes too:"}, {"id": "f4", "type": "textarea", "label": "How we will talk about it afterward without blame:"}]'::jsonb, array['OCD', 'couples', 'values']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('safety-object-carry-audit-sheet', 'Safety Object Carry Audit Sheet', 'worksheet'::resource_kind, 'An audit of the items the client carries in case of panic, what each is for, and which could be left home first.', 'Use it to help a client see what they carry for safety and plan a gentle order for leaving items behind.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to empty their bag in their mind: water bottle, medication they rarely take, a paper bag, phone charger, mints, a specific person''s number on speed dial. For each item, ask what it is protecting against. Rank the items from easiest to hardest to leave home. Agree on the first one to leave behind on a short outing and what they will do if the urge for it shows up.', '[{"id": "f0", "type": "textarea", "label": "The items I carry in case of panic:"}, {"id": "f1", "type": "textarea", "label": "What each one is protecting against:"}, {"id": "f2", "type": "textarea", "label": "Ranked from easiest to hardest to leave at home:"}, {"id": "f3", "type": "textarea", "label": "The item I will leave behind first, and the outing I will try it on:"}, {"id": "f4", "type": "textarea", "label": "What I will do if I wish I had it with me:"}]'::jsonb, array['panic attacks', 'safety behaviors', 'exposure']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('straw-breathing-experiment-sheet', 'Straw Breathing Experiment Sheet', 'cbt'::resource_kind, 'A planned interoceptive experiment in breathing through a narrow straw to bring on breathlessness and test what happens next.', 'Use it to help a client learn that the sensation of not getting enough air rises and passes without harm.', array['Adults', 'Teens']::text[], '20 minutes', 'Run it in session first. The client breathes only through a narrow straw for sixty seconds, then stops and watches the sensations settle. Before starting, write the prediction and the feared outcome. Afterward, record the peak rating and how long the sensations took to fade. Repeat until the rating drops, then plan home practice. Confirm with the client that there is no medical reason to avoid breath exercises.', '[{"id": "f0", "type": "textarea", "label": "My prediction before the first round, and how sure I was:"}, {"id": "f1", "type": "textarea", "label": "Peak sensation rating during the round, out of ten:"}, {"id": "f2", "type": "textarea", "label": "How long the sensations took to settle after I stopped:"}, {"id": "f3", "type": "textarea", "label": "What actually happened compared with what I feared:"}, {"id": "f4", "type": "textarea", "label": "My home practice plan: how many rounds, which days:"}]'::jsonb, array['panic attacks', 'exposure', 'core CBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('alarm-without-a-fire-metaphor-page', 'Alarm Without a Fire Metaphor Page', 'act'::resource_kind, 'A page comparing a panic surge to a smoke alarm going off with no fire, and practicing letting it ring while staying put.', 'Use it to help a client treat a panic surge as a loud alarm to tolerate rather than a fire to flee.', array['Adults', 'Teens']::text[], '20 minutes', 'Describe a smoke alarm set off by burnt toast: deafening, impossible to ignore, and not a fire. Ask the client what they do with a real alarm like that: wave a towel, open a window, wait. Translate each to the surge: slow the exhale, stay in the room, let it ring down. The alarm is not pleasant and the practice is not to like it, only to stop running from the house every time toast burns.', '[{"id": "f0", "type": "textarea", "label": "How my panic alarm sounds and feels when it goes off:"}, {"id": "f1", "type": "textarea", "label": "What I usually do when it starts:"}, {"id": "f2", "type": "textarea", "label": "The towel-waving equivalents I can do while I stay put:"}, {"id": "f3", "type": "textarea", "label": "A recent time the alarm rang and there was no fire:"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself the next time it goes off:"}]'::jsonb, array['panic attacks', 'metaphor', 'willingness']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('describe-the-surge-out-loud-practice-card', 'Describe the Surge Out Loud Practice Card', 'dbt'::resource_kind, 'A card for narrating a panic surge in plain, factual words, aloud or in writing, as it rises and falls.', 'Use it to help a client stay observing during a surge instead of getting swept into the catastrophe story.', array['Adults', 'Teens']::text[], 'One week', 'Teach the describe skill applied to body sensations: my heart is beating fast, my hands are tingling, the thought this is dangerous is here. No judgments and no predictions. Practice in session with a mild sensation first. The client then uses the card during a real surge, speaking quietly or typing into their phone, and notes when the narration became easier than the panic.', '[{"id": "f0", "type": "textarea", "label": "The sensations I described, in plain words:"}, {"id": "f1", "type": "textarea", "label": "The thoughts I named as thoughts:"}, {"id": "f2", "type": "textarea", "label": "A judgment or prediction I caught and left out:"}, {"id": "f3", "type": "textarea", "label": "About when during the surge the describing got easier:"}, {"id": "f4", "type": "textarea", "label": "What was different about this surge compared with one where I did not describe it:"}]'::jsonb, array['panic attacks', 'mindfulness', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('jumping-jacks-heartbeat-discovery-play', 'Jumping Jacks Heartbeat Discovery Play', 'kids'::resource_kind, 'A play session where the child and parent do jumping jacks, feel their hearts race and watch them slow down together.', 'Use it to show a child that a fast heart is something bodies do and can settle on their own.', array['Children']::text[], '20 minutes', 'The parent and child do twenty jumping jacks, then both put a hand on their chest and describe the thump. They sit and count how many breaths until the heart feels slow again. Repeat with running in place or spinning. The child learns that a racing heart has many safe causes and always slows down. The parent models curiosity, not worry, and the pair can draw their hearts before and after.', '[{"id": "f0", "type": "textarea", "label": "What my heart felt like after the jumping jacks:"}, {"id": "f1", "type": "textarea", "label": "How many slow breaths until it felt normal again:"}, {"id": "f2", "type": "textarea", "label": "Other things we did that made our hearts fast:"}, {"id": "f3", "type": "textarea", "label": "Drawing of my heart before and after:"}, {"id": "f4", "type": "textarea", "label": "What I will remember next time my heart races on its own:"}]'::jsonb, array['panic attacks', 'children', 'play']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('sibling-fairness-versus-sameness-sheet', 'Sibling Fairness Versus Sameness Sheet', 'worksheet'::resource_kind, 'A sheet for parents to separate treating children fairly from treating them identically, with examples from the week.', 'Use it to help a parent answer the complaint that is not fair with a clear idea of what fair means in their home.', array['Adults']::text[], '30 minutes', 'Ask the parent for the week''s fairness complaints: bedtime, screen time, who got to choose. For each, ask whether the children''s ages, needs and the situation were the same. Help the parent write a one-line family definition of fair, such as everyone gets what they need, not the same thing. Then draft the sentence they will say the next time a child protests, and what each child does need right now.', '[{"id": "f0", "type": "textarea", "label": "This week''s not fair complaints, and what each child wanted:"}, {"id": "f1", "type": "textarea", "label": "For each one, how the children''s ages and needs differed:"}, {"id": "f2", "type": "textarea", "label": "Our family''s one-line definition of fair:"}, {"id": "f3", "type": "textarea", "label": "What each child needs most right now that the other does not:"}, {"id": "f4", "type": "textarea", "label": "The sentence I will say the next time I hear that it is not fair:"}]'::jsonb, array['parenting', 'family', 'fairness']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('holding-the-limit-thought-record', 'Holding the Limit Thought Record', 'cbt'::resource_kind, 'A thought record for the moment a parent is about to give in to a limit they set, catching the thought that makes caving feel kind.', 'Use it to help a parent hold a limit by testing the thought that pushes them to drop it.', array['Adults']::text[], '20 minutes', 'Ask the parent for the last time they set a limit and then dropped it under protest. Find the thought in the moment: they will think I do not love them, this is too much for them, it is not worth the fight. Weigh the evidence and the likely result of holding versus caving over a month. Write a balanced thought and a holding sentence that the parent can say calmly while the child protests.', '[{"id": "f0", "type": "textarea", "label": "The limit I set, and the moment I started to drop it:"}, {"id": "f1", "type": "textarea", "label": "The thought that made giving in feel like the kind choice:"}, {"id": "f2", "type": "textarea", "label": "Evidence for and against that thought:"}, {"id": "f3", "type": "textarea", "label": "What holding the limit for a month would likely do, and what caving would:"}, {"id": "f4", "type": "textarea", "label": "My balanced thought, and the calm sentence I will say while they protest:"}]'::jsonb, array['parenting', 'core CBT', 'boundaries']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('bedtime-battles-choice-point-page', 'Bedtime Battles Choice Point Page', 'act'::resource_kind, 'A choice point map for the bedtime hour, with the parent''s away moves and toward moves and the hooks that pull them.', 'Use it to help a parent see the bedtime hour as a series of choices toward the parent they want to be.', array['Adults']::text[], '30 minutes', 'Draw the choice point: at the bottom, the bedtime situation and the thoughts and feelings it brings; to the left, away moves like yelling, threatening or giving up; to the right, toward moves that fit the parent they want to be. Name the hooks, often exhaustion and the thought this should be easier. Pick one toward move to practice this week and a way to unhook from the biggest hook.', '[{"id": "f0", "type": "textarea", "label": "What bedtime usually looks like in our house, and what I feel by the end:"}, {"id": "f1", "type": "textarea", "label": "My away moves at bedtime:"}, {"id": "f2", "type": "textarea", "label": "My toward moves, the ones that fit the parent I want to be:"}, {"id": "f3", "type": "textarea", "label": "The hook that pulls me into the away moves most often:"}, {"id": "f4", "type": "textarea", "label": "One toward move I will practice this week, and how I will unhook:"}]'::jsonb, array['parenting', 'choice point', 'values']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('reinforcement-timing-card-for-parents', 'Reinforcement Timing Card for Parents', 'dbt'::resource_kind, 'A card on catching and rewarding a wanted behavior within seconds, with the week''s examples.', 'Use it to help a parent strengthen the behavior they want by noticing it right when it happens.', array['Adults']::text[], 'One week', 'Explain that attention right after a behavior makes it more likely, whatever the behavior, and that most parents respond fastest to misbehavior. Pick one wanted behavior, such as starting homework or speaking kindly to a sibling. The parent''s job this week is to notice and respond within ten seconds with specific attention. Log the catches. Review what got in the way of noticing.', '[{"id": "f0", "type": "textarea", "label": "The behavior I want to see more of:"}, {"id": "f1", "type": "textarea", "label": "The times I caught it this week, and what I said within ten seconds:"}, {"id": "f2", "type": "textarea", "label": "Times I missed it, and what I was doing instead:"}, {"id": "f3", "type": "textarea", "label": "How my child responded to being caught doing well:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about where my attention usually goes:"}]'::jsonb, array['parenting', 'core DBT', 'praise']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('would-you-rather-family-rules-edition', 'Would You Rather: Family Rules Edition', 'game'::resource_kind, 'A would-you-rather game where parents and children pick between two family rules and explain their choice, then make one rule together.', 'Use it to get a family talking about rules without a lecture and to give children a voice in making one.', array['Groups', 'Children', 'Adults']::text[], '30 minutes', 'Prepare cards with two rule options each: would you rather have no screens at dinner or no screens in bedrooms; a chore chart or a chore lottery. Everyone votes with a thumb and the youngest explains first. After ten cards the family drafts one real rule using what they learned about each other. The parent agrees in advance that the drafted rule will be tried for a week.', '[{"id": "f0", "type": "textarea", "label": "The card where our family disagreed most, and what each person said:"}, {"id": "f1", "type": "textarea", "label": "The card where we all agreed:"}, {"id": "f2", "type": "textarea", "label": "Something I learned about why a family member wants a rule:"}, {"id": "f3", "type": "textarea", "label": "The rule we drafted together:"}, {"id": "f4", "type": "textarea", "label": "How the week went with the new rule:"}]'::jsonb, array['parenting', 'game', 'family']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('mental-health-hospital-bag-checklist', 'Mental Health Hospital Bag Checklist', 'worksheet'::resource_kind, 'A checklist of what the client packs for their own steadiness around a birth: people, words, objects and a plan for the first night.', 'Use it to help an expecting parent pack for their mind the way they pack for the baby.', array['Adults']::text[], '30 minutes', 'Alongside the usual hospital bag, build one for the client''s steadiness: a playlist, a photo, a phrase they want to hear, a list of who may visit and who may not, and what they want a partner or support person to say if things get frightening. Include a plan for the first night home. Writing it before the birth gives the client a say in a time when they may have little.', '[{"id": "f0", "type": "textarea", "label": "People I want present, and people I want to wait:"}, {"id": "f1", "type": "textarea", "label": "Words I want to hear from my support person if I get scared:"}, {"id": "f2", "type": "textarea", "label": "Objects that steady me that will fit in a bag:"}, {"id": "f3", "type": "textarea", "label": "What I want the first night home to look like, and who will help:"}, {"id": "f4", "type": "textarea", "label": "If the days after bring thoughts of harming myself, who I will tell (988 by call or text is one option):"}]'::jsonb, array['perinatal and postpartum', 'planning', 'support']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('crying-baby-self-blame-fair-check-sheet', 'Crying Baby Self-Blame Fair Check Sheet', 'cbt'::resource_kind, 'A sheet for the thought that the baby''s crying means the parent is doing something wrong, with the evidence and a fairer read.', 'Use it to help a new parent separate a baby''s crying from a verdict on their parenting.', array['Adults']::text[], '20 minutes', 'Catch the thought in the middle of a long cry: I am failing, they can tell I do not know what I am doing. Lay out what babies cry about, how many of those are about the parent, and what the parent actually did during the cry. Write the fairer thought. Then plan the hand-off: who takes the baby when the parent needs a break, since the thought is loudest when there is no relief.', '[{"id": "f0", "type": "textarea", "label": "The thought that shows up when the crying goes on:"}, {"id": "f1", "type": "textarea", "label": "What babies cry about, and which of those are about me:"}, {"id": "f2", "type": "textarea", "label": "What I actually did during the last long cry:"}, {"id": "f3", "type": "textarea", "label": "A fairer thought, in my own words:"}, {"id": "f4", "type": "textarea", "label": "Who I can hand the baby to for ten minutes, and how I will ask:"}]'::jsonb, array['perinatal and postpartum', 'core CBT', 'self-blame']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('lost-hobbies-postponed-not-gone-page', 'Lost Hobbies Postponed Not Gone Page', 'act'::resource_kind, 'A page for naming the interests a new parent has set aside and sorting them into postponed, shrunk and let go.', 'Use it to help a new parent grieve what is paused and find one interest that fits in a smaller form now.', array['Adults']::text[], '30 minutes', 'List what the client did before the baby that they no longer do. Sort each one: postponed until a specific stage, shrunk to a version that fits now, or truly let go. Mixed feelings about the list are the point; make room for them. Pick one shrunk version to try this week, such as five pages instead of a chapter. The sorting makes the loss specific and smaller than the fog suggests.', '[{"id": "f0", "type": "textarea", "label": "Things I used to do that I have not done since the baby:"}, {"id": "f1", "type": "textarea", "label": "Which of these are postponed, and until roughly when:"}, {"id": "f2", "type": "textarea", "label": "Which could shrink to a version that fits my life now:"}, {"id": "f3", "type": "textarea", "label": "Which I am choosing to let go, and how that feels:"}, {"id": "f4", "type": "textarea", "label": "The shrunk version I will try this week:"}]'::jsonb, array['perinatal and postpartum', 'values', 'acceptance']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('ten-minute-positives-card-for-new-parents', 'Ten Minute Positives Card for New Parents', 'dbt'::resource_kind, 'A card of pleasant activities that fit into ten-minute windows between feeds and naps.', 'Use it to help a new parent accumulate small positives in the only gaps they have.', array['Adults']::text[], 'One week', 'Ask what the client would enjoy if they had an hour, then shrink each to a ten-minute version: one song with eyes closed, a hot drink on the step, a chapter read aloud to the baby, a call to one friend. The window will be interrupted; the skill is starting anyway. Log the windows used and how the client felt afterward, and watch for the thought that ten minutes is not worth it.', '[{"id": "f0", "type": "textarea", "label": "Ten-minute versions of things I enjoy:"}, {"id": "f1", "type": "textarea", "label": "The windows I used this week, and what I did:"}, {"id": "f2", "type": "textarea", "label": "How I felt afterward, even when it got interrupted:"}, {"id": "f3", "type": "textarea", "label": "The thought that tried to stop me from using a window:"}, {"id": "f4", "type": "textarea", "label": "Three I will keep on the card:"}]'::jsonb, array['perinatal and postpartum', 'emotion regulation', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('parental-leave-return-teamwork-sheet', 'Parental Leave Return Teamwork Sheet', 'couples'::resource_kind, 'Partners plan the return to work after leave: handoffs, who covers sick days, pumping or feeding logistics and the first week''s check-in.', 'Use it to help partners share the return to work as a team project rather than one person''s problem.', array['Couples']::text[], 'Full session', 'Set the return date and work backward. Who does the morning handoff, who is called first when the baby is sick, how feeding or pumping fits a workday, and what the returning partner wants to hear at the end of day one. Ask each partner what they are most worried about and write it down. Plan a check-in at the end of week one to adjust. Expect the plan to change; the habit of adjusting together is the goal.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I am most worried about in the return:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I am most worried about in the return:"}, {"id": "f2", "type": "textarea", "label": "Who covers mornings, evenings and sick days in the first month:"}, {"id": "f3", "type": "textarea", "label": "Feeding or pumping logistics, and who handles the supplies:"}, {"id": "f4", "type": "textarea", "label": "What each of us wants to hear at the end of the first day back:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'planning']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('capable-moments-map', 'Capable Moments Map', 'worksheet'::resource_kind, 'A map of the roles and settings where the client already feels capable, and what those settings have in common.', 'Use it to help a client locate the conditions in which their competence shows up and bring them elsewhere.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask where the client feels capable, even briefly: fixing a bike, with a particular friend, in the kitchen, at a certain hour. Draw them as islands on a map. Then ask what the islands share: clear tasks, no audience, a role they chose. Those shared features are portable. Pick one setting where the client feels inadequate and borrow one feature from the islands to try there.', '[{"id": "f0", "type": "textarea", "label": "Places, roles or times where I feel capable, even a little:"}, {"id": "f1", "type": "textarea", "label": "What those settings have in common:"}, {"id": "f2", "type": "textarea", "label": "A setting where I feel inadequate:"}, {"id": "f3", "type": "textarea", "label": "One feature from my capable islands I could bring to that setting:"}, {"id": "f4", "type": "textarea", "label": "What happened when I tried it:"}]'::jsonb, array['self-esteem', 'strengths', 'perspective']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('prejudice-against-myself-sheet', 'Prejudice Against Myself Sheet', 'cbt'::resource_kind, 'A sheet comparing how the client treats evidence about themselves to how a prejudiced person treats evidence about a group.', 'Use it to help a client see a negative core belief as a prejudice that filters evidence rather than a fact.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to describe how someone with a prejudice handles evidence: ignores what does not fit, explains away exceptions, remembers what confirms. Then look at how they handle evidence about their own worth. The parallel usually lands quickly. Choose one piece of evidence they dismissed this week and write how a fair-minded person would file it. Set a week of collecting the filtered-out evidence.', '[{"id": "f0", "type": "textarea", "label": "My negative belief about myself, in one sentence:"}, {"id": "f1", "type": "textarea", "label": "How I handle evidence that does not fit it:"}, {"id": "f2", "type": "textarea", "label": "A piece of evidence I dismissed or explained away this week:"}, {"id": "f3", "type": "textarea", "label": "How a fair-minded person would file that same evidence:"}, {"id": "f4", "type": "textarea", "label": "Evidence I collected this week that the belief would have filtered out:"}]'::jsonb, array['self-esteem', 'core beliefs', 'core CBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('being-average-willingness-practice', 'Being Average Willingness Practice', 'act'::resource_kind, 'A practice in being willing to be ordinary at something this week and noticing what the mind says about it.', 'Use it to help a client whose worth depends on excelling try being average on purpose and survive it.', array['Adults', 'Teens']::text[], 'One week', 'Choose a low-stakes activity the client usually tries to be the best at: a game night, a work email, a workout. The practice is to do it to an ordinary standard, deliberately, and notice the mind''s commentary and the body''s tension. Write the commentary down verbatim. Debrief whether anything the mind predicted actually happened, and what the client did with the energy they did not spend.', '[{"id": "f0", "type": "textarea", "label": "The activity I chose to be average at:"}, {"id": "f1", "type": "textarea", "label": "What my mind said before, during and after, word for word:"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body:"}, {"id": "f3", "type": "textarea", "label": "What actually happened as a result of being ordinary:"}, {"id": "f4", "type": "textarea", "label": "What I did with the energy I did not spend on excelling:"}]'::jsonb, array['self-esteem', 'willingness', 'defusion']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('participate-without-self-monitoring-practice-card', 'Participate Without Self-Monitoring Practice Card', 'dbt'::resource_kind, 'A card for throwing oneself into an activity fully, catching the inner commentator and returning to the activity.', 'Use it to help a client experience doing something without the running self-evaluation.', array['Adults', 'Teens']::text[], 'One week', 'Teach the participate skill: becoming one with the activity, like dancing without watching yourself dance. Pick a daily activity, such as cooking, a walk or a conversation. The client notices when the commentator starts rating them, labels it, and returns to the doing. Log how long they stayed in the activity before the commentator spoke and what happened to enjoyment on the days they returned quickly.', '[{"id": "f0", "type": "textarea", "label": "The activity I practiced with today:"}, {"id": "f1", "type": "textarea", "label": "What the commentator said when it showed up:"}, {"id": "f2", "type": "textarea", "label": "How I returned to the activity:"}, {"id": "f3", "type": "textarea", "label": "How enjoyable the activity was, out of ten, on days I stayed in it:"}, {"id": "f4", "type": "textarea", "label": "The activity I want to try participating fully in next:"}]'::jsonb, array['self-esteem', 'mindfulness', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('me-puppet-interview-show', 'Me Puppet Interview Show', 'kids'::resource_kind, 'The child makes a puppet of themselves and a parent interviews it on a pretend talk show about what the puppet is good at and likes.', 'Use it to let a child talk about their strengths through a puppet when saying nice things about themselves feels hard.', array['Children']::text[], '30 minutes', 'The child makes a paper bag or sock puppet that looks like them. The parent hosts a talk show and interviews the puppet: what are you great at, what do your friends like about you, what did you do that was hard this week. The puppet answers. Children will often say through the puppet what they would never say as themselves. The parent ends by telling the puppet something true they admire about it.', '[{"id": "f0", "type": "textarea", "label": "My puppet''s name and what it looks like:"}, {"id": "f1", "type": "textarea", "label": "What my puppet said it is great at:"}, {"id": "f2", "type": "textarea", "label": "What my puppet said its friends like about it:"}, {"id": "f3", "type": "textarea", "label": "Something hard my puppet did this week:"}, {"id": "f4", "type": "textarea", "label": "What my grown-up told my puppet they admire:"}]'::jsonb, array['self-esteem', 'children', 'play']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('group-entry-points-map', 'Group Entry Points Map', 'worksheet'::resource_kind, 'A map of a typical gathering with the spots and moments that make joining easier, drawn before the event.', 'Use it to help a client plan where to stand, who to approach and when, instead of hovering at the edge.', array['Adults', 'Teens']::text[], '20 minutes', 'Before a real event, sketch the room: the food table, the kitchen, the host, the quiet corner. Mark the entry points: the person who is also alone, the host who introduces people, the task that gives a reason to talk, like helping carry plates. Plan the first ten minutes with two entry points. Afterward, mark which worked. Clients learn that joining is a set of spots and moments, not a leap.', '[{"id": "f0", "type": "textarea", "label": "The event, and a sketch of where things will be:"}, {"id": "f1", "type": "textarea", "label": "Entry points I can see: people, tasks, moments:"}, {"id": "f2", "type": "textarea", "label": "My plan for the first ten minutes:"}, {"id": "f3", "type": "textarea", "label": "Which entry points I used, and how each went:"}, {"id": "f4", "type": "textarea", "label": "What I will look for first at the next gathering:"}]'::jsonb, array['social anxiety', 'planning', 'exposure']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('ask-a-stranger-for-directions-experiment-sheet', 'Ask a Stranger for Directions Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment in asking three strangers for directions and recording their responses against the prediction.', 'Use it to help a client test the belief that bothering strangers leads to annoyance or ridicule.', array['Adults', 'Teens']::text[], 'One week', 'Pick a public place and a plausible question: where is the nearest pharmacy, which platform for this train. Write the prediction about how strangers will react and the client''s rating of how unbearable it will feel. The client asks three people over the week and records each response in detail: face, words, tone. Debrief the gap between prediction and record and what they would try next.', '[{"id": "f0", "type": "textarea", "label": "My prediction about how strangers will react, and how sure I am:"}, {"id": "f1", "type": "textarea", "label": "Person one: what I asked, their words, face and tone:"}, {"id": "f2", "type": "textarea", "label": "Person two: what I asked, their words, face and tone:"}, {"id": "f3", "type": "textarea", "label": "Person three: what I asked, their words, face and tone:"}, {"id": "f4", "type": "textarea", "label": "What the three responses tell me about my prediction:"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'core CBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('fitting-in-versus-belonging-values-page', 'Fitting In Versus Belonging Values Page', 'act'::resource_kind, 'A page separating the effort to fit in by hiding from the kind of belonging the client actually wants.', 'Use it to help a client see what social anxiety has them performing and what connection they value instead.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to list what they do to fit in at gatherings: agree with everything, hide opinions, laugh on cue, leave early. Then ask what belonging would look like: being known, disagreeing kindly, staying. The first list is about avoiding rejection; the second is about a value. Choose one small act of belonging for the next event and notice what the fitting-in habits say about it.', '[{"id": "f0", "type": "textarea", "label": "Things I do to fit in that involve hiding part of myself:"}, {"id": "f1", "type": "textarea", "label": "What belonging, as opposed to fitting in, would look like for me:"}, {"id": "f2", "type": "textarea", "label": "The value underneath wanting to belong:"}, {"id": "f3", "type": "textarea", "label": "One small act of belonging I will try at the next event:"}, {"id": "f4", "type": "textarea", "label": "What the fitting-in habits said when I tried it, and what I did:"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('describe-the-room-not-myself-card', 'Describe the Room Not Myself Card', 'dbt'::resource_kind, 'A card for pointing the observe and describe skills outward in a social setting, at the room and the people, not at the self.', 'Use it to help a client move attention off their own performance and onto what is actually in the room.', array['Adults', 'Teens']::text[], 'One week', 'Teach the client to observe and describe outward when self-focus climbs: the color of the walls, what the person across the table is saying, the number of people wearing blue. No judgments and nothing about how they are coming across. Use the card at one event this week and rate self-focus before and after each round of describing. Review what they actually learned about the room.', '[{"id": "f0", "type": "textarea", "label": "The event, and my self-focus rating when I arrived:"}, {"id": "f1", "type": "textarea", "label": "Things I observed and described about the room:"}, {"id": "f2", "type": "textarea", "label": "Things I observed and described about the people, without judging:"}, {"id": "f3", "type": "textarea", "label": "My self-focus rating after a round of describing:"}, {"id": "f4", "type": "textarea", "label": "Something I learned about someone there because I was looking outward:"}]'::jsonb, array['social anxiety', 'mindfulness', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('speed-chat-rotation-game', 'Speed Chat Rotation Game', 'game'::resource_kind, 'Players rotate through two-minute chats with a new partner each round, using a prompt card, then debrief what got easier.', 'Use it to give a group many short, low-stakes conversation reps in one session.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Set chairs in two rows facing each other. Each round, a prompt card is read, such as the best thing you ate this week, and pairs talk for two minutes. Then one row shifts a seat. Run six to eight rounds. Rules: no phones, and anyone may pass on a prompt. Debrief which round felt easiest, what players noticed about repetition, and one thing they learned about someone they had not spoken to before.', '[{"id": "f0", "type": "textarea", "label": "The round that felt hardest, and the one that felt easiest:"}, {"id": "f1", "type": "textarea", "label": "What changed in my body between the first and last round:"}, {"id": "f2", "type": "textarea", "label": "A prompt that worked well, and one I would change:"}, {"id": "f3", "type": "textarea", "label": "Something I learned about a person I had not talked to before:"}, {"id": "f4", "type": "textarea", "label": "One opener from the game I could use outside the group:"}]'::jsonb, array['social anxiety', 'game', 'social skills']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('sayings-i-carry-from-them-page', 'Sayings I Carry From Them Page', 'worksheet'::resource_kind, 'A page for collecting the phrases, jokes and advice the person who died used to say, and when each still shows up.', 'Use it to help a client keep a living connection through the words that were theirs.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client what the person used to say: the catchphrase, the terrible pun, the advice they gave every time. Write each one down in the person''s voice. Then ask when each saying shows up now, uninvited or on purpose. Some clients choose one saying to use aloud this week. The page honors the relationship as it continues rather than asking the client to put it away.', '[{"id": "f0", "type": "textarea", "label": "Things they always used to say:"}, {"id": "f1", "type": "textarea", "label": "The one that makes me laugh, and the one that makes me ache:"}, {"id": "f2", "type": "textarea", "label": "When these sayings show up in my days now:"}, {"id": "f3", "type": "textarea", "label": "A saying I might use out loud this week, and with whom:"}, {"id": "f4", "type": "textarea", "label": "What it is like to hear their words in my own voice:"}]'::jsonb, array['grief and loss', 'continuing bonds', 'memory']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('guilt-over-relief-thought-check', 'Guilt Over Relief Thought Check', 'cbt'::resource_kind, 'A thought check for the guilt that follows feeling relief after a long illness or a hard relationship ends in a death.', 'Use it to help a client make sense of relief in grief without reading it as proof of not having loved.', array['Adults']::text[], '30 minutes', 'Relief after a long illness or a hard relationship is common and rarely spoken. Catch the thought: feeling relieved means I wanted this, or means I did not love them. Look at what the relief is actually about: the end of suffering, of vigilance, of the fear of the phone ringing. Both feelings can be true at once. Write a thought that holds the love and the relief together.', '[{"id": "f0", "type": "textarea", "label": "The relief I have felt, and when it shows up:"}, {"id": "f1", "type": "textarea", "label": "The thought that turns the relief into guilt:"}, {"id": "f2", "type": "textarea", "label": "What the relief is actually about, specifically:"}, {"id": "f3", "type": "textarea", "label": "Evidence that love and relief can exist at the same time:"}, {"id": "f4", "type": "textarea", "label": "A thought that holds both, in my own words:"}]'::jsonb, array['grief and loss', 'guilt', 'core CBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('grief-as-love-with-nowhere-to-go-page', 'Grief as Love With Nowhere to Go Page', 'act'::resource_kind, 'A page working with the idea that grief is love that has lost its usual destination, and choosing where some of it can go now.', 'Use it to help a client make room for grief as love and find one place for that love to land.', array['Adults', 'Teens']::text[], '30 minutes', 'Offer the idea that the ache is love that used to have somewhere to go: a phone call, a Sunday dinner, a worry. Ask what the love used to do each week. Then, without rushing, ask where some of it could land now: a person, a cause they cared about, a habit they shared. The grief stays; this is not a replacement. It is willingness to let the love keep moving while the ache comes along.', '[{"id": "f0", "type": "textarea", "label": "What my love for them used to do each week:"}, {"id": "f1", "type": "textarea", "label": "What the ache feels like now, as a feeling in the body:"}, {"id": "f2", "type": "textarea", "label": "People, causes or habits where some of that love could land:"}, {"id": "f3", "type": "textarea", "label": "One place I will let it land this week:"}, {"id": "f4", "type": "textarea", "label": "What I notice about carrying the ache while the love moves:"}]'::jsonb, array['grief and loss', 'acceptance', 'values']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-the-unfinished-conversation-card', 'Radical Acceptance of the Unfinished Conversation Card', 'dbt'::resource_kind, 'A card for turning the mind toward the conversation that never happened and cannot now, with coping statements for when the mind fights it.', 'Use it to help a client practice accepting that a conversation stays unfinished, without approving of that fact.', array['Adults', 'Teens']::text[], 'One week', 'Name the conversation: the apology, the question, the thank-you. Teach that radical acceptance does not mean it is okay; it means it is what is. Write the acceptance statement in the client''s words and two coping statements for the moments the mind replays it. Practice turning the mind each time the replay starts. If the client wants to write the unsent words, pair with an unsent letter, but keep this card about accepting.', '[{"id": "f0", "type": "textarea", "label": "The conversation that stays unfinished:"}, {"id": "f1", "type": "textarea", "label": "My acceptance statement, in my words:"}, {"id": "f2", "type": "textarea", "label": "Two coping statements for when my mind replays it:"}, {"id": "f3", "type": "textarea", "label": "The times this week I turned my mind back toward acceptance:"}, {"id": "f4", "type": "textarea", "label": "What changed in the replay as the week went on:"}]'::jsonb, array['grief and loss', 'radical acceptance', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('holiday-roles-they-used-to-hold-sheet', 'Holiday Roles They Used to Hold Sheet', 'couples'::resource_kind, 'Partners list the roles the person who died used to hold on holidays and decide together which to take up, share, change or retire.', 'Use it to help partners plan a first holiday without the person without one of them silently taking on everything.', array['Couples']::text[], 'Full session', 'List what the person did on the holiday: hosted, carved, said grace, called the relatives, made the one dish. For each role, the partners decide: one of us takes it, we share it, we change it, or we let it rest this year. Watch for one partner volunteering for everything. End with a plan for a pause during the day, since the grief will arrive whatever the roles are.', '[{"id": "f0", "type": "textarea", "label": "The roles they held on the holiday:"}, {"id": "f1", "type": "textarea", "label": "Partner A: roles I want to take or share, and ones I cannot this year:"}, {"id": "f2", "type": "textarea", "label": "Partner B: roles I want to take or share, and ones I cannot this year:"}, {"id": "f3", "type": "textarea", "label": "Roles we will change or let rest this year:"}, {"id": "f4", "type": "textarea", "label": "Our plan for a pause during the day when the grief arrives:"}]'::jsonb, array['grief and loss', 'couples', 'rituals']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('unspoken-expectations-audit', 'Unspoken Expectations Audit', 'worksheet'::resource_kind, 'An audit of the expectations the client holds for friends, family or a partner that they have never actually said out loud.', 'Use it to help a client find the resentments that come from rules nobody else knows about.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask about recent moments of disappointment with someone close. For each, find the expectation underneath: they should have texted first, remembered, offered. Then ask whether the client ever said it aloud. Most have not. Sort the expectations into ones worth saying, ones worth dropping, and ones to keep but hold more lightly. Draft the sentence for one worth saying.', '[{"id": "f0", "type": "textarea", "label": "Recent disappointments with people close to me:"}, {"id": "f1", "type": "textarea", "label": "The expectation underneath each one:"}, {"id": "f2", "type": "textarea", "label": "Which of these I have actually said out loud:"}, {"id": "f3", "type": "textarea", "label": "Which are worth saying, worth dropping, or worth keeping more lightly:"}, {"id": "f4", "type": "textarea", "label": "The sentence I will use to say one of them this week:"}]'::jsonb, array['relationship issues', 'communication', 'needs']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('scorekeeping-thought-check-sheet', 'Scorekeeping Thought Check Sheet', 'cbt'::resource_kind, 'A sheet for catching the running tally of who did more and testing what keeping score does to the relationship.', 'Use it to help a client notice scorekeeping thoughts and weigh what they cost.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to write their current tally: I did the dishes four times, they did them once. Then look at what the tally leaves out, what the other person might be tallying, and what the client feels while counting. Ask what the score is for and what it gets them. Scorekeeping usually protects against being taken for granted while making closeness impossible. Draft the request underneath the score.', '[{"id": "f0", "type": "textarea", "label": "My current tally, honestly:"}, {"id": "f1", "type": "textarea", "label": "What the tally leaves out, and what the other person might be counting:"}, {"id": "f2", "type": "textarea", "label": "What I feel while I am counting:"}, {"id": "f3", "type": "textarea", "label": "What the score is protecting me from, and what it costs:"}, {"id": "f4", "type": "textarea", "label": "The request underneath the score, said plainly:"}]'::jsonb, array['relationship issues', 'thinking traps', 'core CBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('old-pattern-new-move-choice-page', 'Old Pattern New Move Choice Page', 'act'::resource_kind, 'A page for mapping one recurring relationship pattern and choosing a single new move at the point where the old one usually fires.', 'Use it to help a client change one step in a familiar dance rather than the whole dance at once.', array['Adults', 'Teens']::text[], '30 minutes', 'Map the pattern as steps: they do this, I do that, they do this. Find the step where the client''s move is most automatic, often withdrawing or escalating. Ask what value they want to act from at that moment and what one different move would look like. Plan to try the new move once this week with the old urge fully present. Change one step, and the dance has to change around it.', '[{"id": "f0", "type": "textarea", "label": "The pattern, step by step:"}, {"id": "f1", "type": "textarea", "label": "The step where my move is most automatic:"}, {"id": "f2", "type": "textarea", "label": "The value I want to act from at that moment:"}, {"id": "f3", "type": "textarea", "label": "The one new move I will try, and what the old urge will say:"}, {"id": "f4", "type": "textarea", "label": "What happened when I tried it:"}]'::jsonb, array['relationship issues', 'committed action', 'pattern']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('what-got-in-the-way-interpersonal-review', 'What Got in the Way Interpersonal Review', 'dbt'::resource_kind, 'A review of one interpersonal attempt that did not go as planned, checking skills, environment, emotion, worry thoughts and indecision.', 'Use it to help a client find the specific reason an interpersonal attempt went wrong before trying again.', array['Adults', 'Teens']::text[], '20 minutes', 'Take one recent attempt to ask, refuse or repair that did not work. Check each cause in order: did they lack a skill or forget to use it, did the environment make it impossible, were emotions too high, did worry thoughts interfere, or could they not decide what they wanted. Each points to a different fix. End with the plan for the next attempt that targets the actual cause.', '[{"id": "f0", "type": "textarea", "label": "What I tried to do, and what happened:"}, {"id": "f1", "type": "textarea", "label": "Did I have the skill and use it? What did I skip?"}, {"id": "f2", "type": "textarea", "label": "Was the environment or the other person making it impossible?"}, {"id": "f3", "type": "textarea", "label": "Were emotions too high, or were worry thoughts in the way? Which thoughts?"}, {"id": "f4", "type": "textarea", "label": "Was I unsure what I wanted? My plan for the next attempt:"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('fair-play-rules-poster-craft', 'Fair Play Rules Poster Craft', 'kids'::resource_kind, 'A poster the child makes of rules for playing with friends, such as taking turns and what to do when someone gets upset.', 'Use it to help a child who struggles with friends build their own picture of what fair play looks like.', array['Children']::text[], '30 minutes', 'Ask the child about a recent playtime that went badly and one that went well. Together, turn what they learned into four or five rules in their words: we take turns picking the game, if someone is sad we ask what is wrong. The child draws each rule. The parent helps pick a spot to hang the poster and reads it with the child before a playdate, then asks afterward which rules were easy and hard.', '[{"id": "f0", "type": "textarea", "label": "A time playing with a friend went badly, and what happened:"}, {"id": "f1", "type": "textarea", "label": "A time it went well, and what was different:"}, {"id": "f2", "type": "textarea", "label": "My fair play rules, in my words:"}, {"id": "f3", "type": "textarea", "label": "The rule that is hardest for me:"}, {"id": "f4", "type": "textarea", "label": "After my next playdate: which rules we used:"}]'::jsonb, array['relationship issues', 'children', 'social skills']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('shower-and-bath-grounding-routine-sheet', 'Shower and Bath Grounding Routine Sheet', 'worksheet'::resource_kind, 'A routine for body-care moments that can bring up distress: what the client sees, hears and holds to stay present.', 'Use it to help a client make washing and dressing more predictable and anchored in the present.', array['Adults', 'Teens']::text[], '20 minutes', 'Some clients find showering, bathing or dressing is where distress arrives. Build a present-day routine: a specific playlist or podcast, a scented product chosen for today, the door locked or unlocked as they prefer, a set order of steps, a textured towel to hold afterward. Nothing on this sheet asks what happened; it is about making a daily task feel safer and more the client''s own.', '[{"id": "f0", "type": "textarea", "label": "What I will listen to while I wash or dress:"}, {"id": "f1", "type": "textarea", "label": "A scent or texture I choose because I like it today:"}, {"id": "f2", "type": "textarea", "label": "The order of steps I will follow each time:"}, {"id": "f3", "type": "textarea", "label": "How I want the door, the light and the time of day:"}, {"id": "f4", "type": "textarea", "label": "What I will hold or do right afterward to land back in the room:"}]'::jsonb, array['sexual abuse', 'grounding', 'safety']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('telling-someone-safe-thought-check', 'Telling Someone Safe Thought Check', 'cbt'::resource_kind, 'A thought check for the rules in a survivor''s mind about who may be told and what will happen if they tell.', 'Use it to help a client look at the old rule about telling as a thought that can be examined, at their own pace.', array['Adults', 'Teens']::text[], '30 minutes', 'Do this in session, not as homework. Name the rule the client carries, such as telling anyone will ruin everything or no one will believe me. Treat it as a thought from a time when it may have been true. Look at the present: who in the client''s life now has shown they can be trusted with hard things, and with what. The client decides whether to tell anyone; this sheet examines the rule, nothing more. No details of events are needed.', '[{"id": "f0", "type": "textarea", "label": "The rule in my head about telling, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "Where that rule probably came from, without the details:"}, {"id": "f2", "type": "textarea", "label": "People in my life now who have handled hard things well:"}, {"id": "f3", "type": "textarea", "label": "What I think would actually happen if I told one of them something small:"}, {"id": "f4", "type": "textarea", "label": "What I want to do with this rule for now (keep, loosen, test, or leave it alone):"}]'::jsonb, array['sexual abuse', 'core CBT', 'support']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('trust-at-my-own-speed-practice-page', 'Trust at My Own Speed Practice Page', 'act'::resource_kind, 'A practice in letting trust build at the client''s own pace, noticing the mind''s pressure to hurry or to shut the door.', 'Use it to help a client treat the pace of trust as theirs to set, in service of connection.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client about a relationship, new or old, where trust is in question. Notice the two pushes: the one that says hurry up and be normal, and the one that says never again. Both are the mind protecting. Ask what trust at their own speed would look like this month: one small shared thing, kept small. Make room for the discomfort of going slowly on purpose. Pace is the client''s; the practice is choosing it.', '[{"id": "f0", "type": "textarea", "label": "The relationship where trust is in question:"}, {"id": "f1", "type": "textarea", "label": "What the hurry-up push says, and what the never-again push says:"}, {"id": "f2", "type": "textarea", "label": "What trust at my own speed would look like this month:"}, {"id": "f3", "type": "textarea", "label": "One small shared thing I am willing to try, kept small:"}, {"id": "f4", "type": "textarea", "label": "What I notice about choosing the pace myself:"}]'::jsonb, array['sexual abuse', 'values', 'pacing']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('self-validation-after-a-flashback-card', 'Self-Validation After a Flashback Card', 'dbt'::resource_kind, 'A card of self-validation statements for the minutes after a flashback or intense reminder, used once the client is grounded.', 'Use it to help a client speak to themselves with understanding after a hard moment instead of with criticism.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the card in session, after a grounding practice the client already knows. Write three statements in the client''s words that validate the reaction without analyzing it: of course my body reacted, it makes sense that I needed a minute, I did what I could. Add the first grounding step and one person to contact. The card is for afterward; it never asks what the reminder was about.', '[{"id": "f0", "type": "textarea", "label": "Three statements that make sense of my reaction, in my words:"}, {"id": "f1", "type": "textarea", "label": "The first grounding step I will take before I read them:"}, {"id": "f2", "type": "textarea", "label": "What I usually say to myself afterward that I want to replace:"}, {"id": "f3", "type": "textarea", "label": "Who I can text or call if I need a voice (988 by call or text is always an option):"}, {"id": "f4", "type": "textarea", "label": "What I will do for myself in the hour after:"}]'::jsonb, array['sexual abuse', 'validation', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('secrets-versus-surprises-sorting-game', 'Secrets Versus Surprises Sorting Game', 'game'::resource_kind, 'A card game for young children sorting happy surprises that get told soon from secrets that feel bad and should always be told.', 'Use it to teach children the difference between a surprise and a secret and who to tell about secrets.', array['Children', 'Groups']::text[], '20 minutes', 'Make cards with simple scenarios: a birthday present for Dad, a grown-up who says do not tell anyone about a touch, a friend''s surprise party, someone showing a picture that made you feel funny. Children take turns placing each card under surprise or secret and say who they would tell. The debrief names three safe grown-ups each child can go to. If a child discloses during the game, follow your reporting duties and stay calm and warm.', '[{"id": "f0", "type": "textarea", "label": "Cards that were surprises, and why they were okay:"}, {"id": "f1", "type": "textarea", "label": "Cards that were secrets, and why they should be told:"}, {"id": "f2", "type": "textarea", "label": "The card that was tricky to sort:"}, {"id": "f3", "type": "textarea", "label": "Three grown-ups I can tell a secret to:"}, {"id": "f4", "type": "textarea", "label": "What I would say to a grown-up if someone asked me to keep a bad secret:"}]'::jsonb, array['sexual abuse', 'children', 'game']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('retired-coping-skills-review-sheet', 'Retired Coping Skills Review Sheet', 'worksheet'::resource_kind, 'A review of coping skills that used to work and no longer do, asking what changed and whether each needs updating or retiring.', 'Use it to help a client update their coping toolkit instead of concluding that nothing works.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask what used to help two years ago, five years ago, as a teenager. Then ask what changed: the skill, the life, the problem. Some skills just need a new form: the long run becomes a walk; the call to a friend who moved becomes a text to a new one. Others earned retirement. Sort them, and pick one to update this week. The frame matters: skills expire, the client has not failed.', '[{"id": "f0", "type": "textarea", "label": "Coping skills that used to work for me:"}, {"id": "f1", "type": "textarea", "label": "What changed since they worked: me, my life or the problem:"}, {"id": "f2", "type": "textarea", "label": "Which could work again in a new form, and what form:"}, {"id": "f3", "type": "textarea", "label": "Which have earned retirement:"}, {"id": "f4", "type": "textarea", "label": "The one I will update and try this week:"}]'::jsonb, array['coping skills', 'skills', 'perspective']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('twenty-minute-rule-coping-experiment', 'Twenty Minute Rule Coping Experiment', 'cbt'::resource_kind, 'An experiment in using a coping skill for a full twenty minutes before judging it, with ratings at the start, ten and twenty minutes.', 'Use it to help a client test the belief that a skill does not work when they have only given it two minutes.', array['Adults', 'Teens']::text[], 'One week', 'Clients often try a skill briefly, feel no change and conclude it failed. Choose one skill. The rule for the week is twenty minutes, with distress ratings at zero, ten and twenty. Write the prediction first. Review the curve: many skills show their effect between minutes ten and twenty. If a skill shows nothing across three twenty-minute trials, that is useful data too.', '[{"id": "f0", "type": "textarea", "label": "The skill I am testing, and my prediction:"}, {"id": "f1", "type": "textarea", "label": "Trial one: ratings at zero, ten and twenty minutes:"}, {"id": "f2", "type": "textarea", "label": "Trial two: ratings at zero, ten and twenty minutes:"}, {"id": "f3", "type": "textarea", "label": "Trial three: ratings at zero, ten and twenty minutes:"}, {"id": "f4", "type": "textarea", "label": "What the curves tell me about how long this skill needs:"}]'::jsonb, array['coping skills', 'behavioral experiment', 'core CBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('coping-skills-as-weather-gear-metaphor-page', 'Coping Skills as Weather Gear Metaphor Page', 'act'::resource_kind, 'A page comparing coping skills to raincoats and boots: gear for getting somewhere in bad weather, not a way to stop the rain.', 'Use it to help a client see coping skills as support for valued action rather than a way to make feelings go away.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client what they expect a coping skill to do. Many expect it to stop the rain. Offer the image of weather gear: it does not change the sky, it lets you walk to the place you were going. Match each of their skills to a piece of gear and name the destination: the meeting, the party, the hard conversation. Skills rated by whether the rain stopped look like failures; rated by whether they got there, they often look like wins.', '[{"id": "f0", "type": "textarea", "label": "What I have been expecting my coping skills to do:"}, {"id": "f1", "type": "textarea", "label": "My skills, matched to pieces of weather gear:"}, {"id": "f2", "type": "textarea", "label": "The places I am trying to get to in bad weather:"}, {"id": "f3", "type": "textarea", "label": "A recent time a skill got me there even though the rain kept falling:"}, {"id": "f4", "type": "textarea", "label": "How I will rate my skills from now on:"}]'::jsonb, array['coping skills', 'metaphor', 'values']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('encouragement-note-for-the-hard-moment-card', 'Encouragement Note for the Hard Moment Card', 'dbt'::resource_kind, 'A card the client writes to their future self for the next hard moment, using the encouragement step of IMPROVE.', 'Use it to give a client their own voice to read when the hard moment makes every other voice go quiet.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the note in session while the client is steady. It speaks to the client in the hard moment: what they have gotten through before, what is true now, what to do first. Keep it believable; a client in distress rejects cheer. Add one line about who to reach if the moment includes thoughts of self-harm. The card lives in a wallet or phone and is read aloud when needed.', '[{"id": "f0", "type": "textarea", "label": "Dear me in the hard moment: what I want you to remember about what you have gotten through:"}, {"id": "f1", "type": "textarea", "label": "What is true right now, even though it does not feel like it:"}, {"id": "f2", "type": "textarea", "label": "The first thing to do, before anything else:"}, {"id": "f3", "type": "textarea", "label": "If the moment includes thoughts of hurting yourself, who to call or text (988 is always an option):"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this card:"}]'::jsonb, array['coping skills', 'core DBT', 'self-talk']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('coping-styles-compare-and-combine-sheet-for-partners', 'Coping Styles Compare and Combine Sheet for Partners', 'couples'::resource_kind, 'Partners each describe how they cope under stress, see where the styles clash, and agree on how to support each other''s way.', 'Use it to help partners stop reading each other''s coping style as rejection or drama.', array['Couples']::text[], '30 minutes', 'Each partner describes what they do under stress: go quiet, talk it through, clean, exercise, scroll. Then each says what the other''s style looks like from the outside. Going quiet can read as shutting out; talking it through can read as needing to be fixed. Agree on what each needs from the other during their style and one combined move for when both are stressed at once.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I cope under stress, and what I need from you while I do it:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I cope under stress, and what I need from you while I do it:"}, {"id": "f2", "type": "textarea", "label": "How each of our styles looks from the other''s side:"}, {"id": "f3", "type": "textarea", "label": "A time our styles clashed, and what each of us thought it meant:"}, {"id": "f4", "type": "textarea", "label": "Our combined move for when we are both stressed at the same time:"}]'::jsonb, array['coping skills', 'couples', 'support']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('flight-day-step-plan-sheet', 'Flight Day Step Plan Sheet', 'worksheet'::resource_kind, 'An hour-by-hour plan for the day of a flight, from packing to landing, with the skill or support for each step.', 'Use it to help a client with a fear of flying walk through the day in order with a plan at each point.', array['Adults', 'Teens']::text[], '30 minutes', 'Break the day into steps: packing, the drive, security, the gate, boarding, taxi, takeoff, cruising, turbulence, descent, landing. For each, write what the client expects to feel and which skill or person they will use. Mark the step they dread most and plan it in extra detail. Having a plan for turbulence often matters more than the plan for takeoff. Review it after the flight to adjust for next time.', '[{"id": "f0", "type": "textarea", "label": "The steps of my flight day, in order:"}, {"id": "f1", "type": "textarea", "label": "What I expect to feel at each step:"}, {"id": "f2", "type": "textarea", "label": "The skill or support I will use at each step:"}, {"id": "f3", "type": "textarea", "label": "The step I dread most, planned in extra detail:"}, {"id": "f4", "type": "textarea", "label": "After the flight: which steps went as planned, and what I will change:"}]'::jsonb, array['phobias', 'planning', 'exposure']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('disgust-rating-practice-log', 'Disgust Rating Practice Log', 'cbt'::resource_kind, 'A log for phobias where disgust, not just fear, drives avoidance, rating both separately during practice steps.', 'Use it to help a client see that disgust and fear move differently during practice and plan for both.', array['Adults', 'Teens']::text[], 'Two weeks', 'Some phobias, such as spiders, blood or vomit, carry as much disgust as fear. Clients rate fear and feel discouraged when something still feels gross. Rate both on separate scales during each practice step. Disgust typically fades more slowly and benefits from longer, repeated contact. Seeing the two lines separately keeps the client from reading slow disgust change as failure.', '[{"id": "f0", "type": "textarea", "label": "The practice step I did, and for how long:"}, {"id": "f1", "type": "textarea", "label": "Fear rating at the start, peak and end:"}, {"id": "f2", "type": "textarea", "label": "Disgust rating at the start, peak and end:"}, {"id": "f3", "type": "textarea", "label": "Which one dropped faster, and which lingered:"}, {"id": "f4", "type": "textarea", "label": "What I will repeat or lengthen next time to work on the lingering one:"}]'::jsonb, array['phobias', 'exposure', 'self-monitoring']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('fear-volume-knob-not-off-switch-page', 'Fear Volume Knob Not Off Switch Page', 'act'::resource_kind, 'A page replacing the goal of switching fear off with the willingness to act while the volume is up.', 'Use it to help a client drop the demand that fear must be gone before they approach the feared thing.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client what they are waiting for before they approach the feared thing. Usually it is for fear to hit zero. Offer the image of a volume knob with no off switch: fear can be loud or quiet, and the hand on the knob is not theirs. What is theirs is where they walk while it plays. Pick a step they would take at a volume of six and plan it, with the fear expected to be along.', '[{"id": "f0", "type": "textarea", "label": "What I have been waiting for before I approach the thing I fear:"}, {"id": "f1", "type": "textarea", "label": "What the fear sounds like at full volume, and at a quiet setting:"}, {"id": "f2", "type": "textarea", "label": "A step I would take if the volume were at six:"}, {"id": "f3", "type": "textarea", "label": "What my mind says about taking it before the volume drops:"}, {"id": "f4", "type": "textarea", "label": "When I will take the step, with the fear along:"}]'::jsonb, array['phobias', 'willingness', 'metaphor']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('check-the-facts-for-a-feared-animal-card', 'Check the Facts for a Feared Animal Card', 'dbt'::resource_kind, 'A card applying check the facts to one feared animal: the interpretation, the actual facts, and whether the fear fits the facts.', 'Use it to help a client separate what they believe about a feared animal from what is actually so.', array['Adults', 'Teens']::text[], '20 minutes', 'Name the animal and the client''s interpretation: it will jump at me, it wants to bite, it is everywhere. Gather the facts together in session from a reliable source, such as how the animal actually behaves around people and how rare harm is. Ask whether the intensity of the fear fits the facts. If it does not, plan the opposite action step. If part of it does, plan the sensible precaution and the step.', '[{"id": "f0", "type": "textarea", "label": "The animal, and what I believe it will do:"}, {"id": "f1", "type": "textarea", "label": "The facts we found about how it actually behaves around people:"}, {"id": "f2", "type": "textarea", "label": "Does my fear fit the facts, in intensity and in kind?"}, {"id": "f3", "type": "textarea", "label": "The sensible precaution, if any, that the facts support:"}, {"id": "f4", "type": "textarea", "label": "The opposite action step I will take, with the facts in hand:"}]'::jsonb, array['phobias', 'check the facts', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('dog-safety-rules-and-petting-steps-poster', 'Dog Safety Rules and Petting Steps Poster', 'kids'::resource_kind, 'A poster the child makes of how to be safe around dogs and the small steps toward petting one, with a parent as helper.', 'Use it to give a child afraid of dogs a set of rules that make them safer and a staircase toward a calm dog.', array['Children']::text[], '30 minutes', 'The child draws the rules: ask the owner first, let the dog sniff a closed hand, no running or screaming, leave a dog that is eating alone. Then draw a staircase of steps: look at a dog across the street, stand near a calm dog on a leash, let it sniff, pet its back. The parent finds a calm dog they know and goes up one step at a time, only when the child says go. Celebrate each step on the poster.', '[{"id": "f0", "type": "textarea", "label": "My dog safety rules, drawn and in my words:"}, {"id": "f1", "type": "textarea", "label": "My staircase of steps toward petting a calm dog:"}, {"id": "f2", "type": "textarea", "label": "The dog my grown-up and I will practice with:"}, {"id": "f3", "type": "textarea", "label": "The step I did today, and how it felt:"}, {"id": "f4", "type": "textarea", "label": "The next step I will try when I am ready:"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('being-in-photos-comfort-steps-sheet', 'Being in Photos Comfort Steps Sheet', 'worksheet'::resource_kind, 'A set of small steps toward being in photos again, from looking at one old picture to being in a group shot.', 'Use it to help a client who avoids cameras rebuild comfort with being seen in pictures, one step at a time.', array['Adults', 'Teens']::text[], 'Two weeks', 'Ask what the client does when a camera comes out: hides, takes the picture, deletes afterward. Build steps from easiest to hardest: look at an old photo for a minute, stay in a group shot without checking it, let someone keep a candid, post nothing but keep one. The client sets the order and the pace. Nothing here is about how the body looks; it is about staying in the picture of their own life.', '[{"id": "f0", "type": "textarea", "label": "What I do now when someone takes out a camera:"}, {"id": "f1", "type": "textarea", "label": "My steps, from easiest to hardest:"}, {"id": "f2", "type": "textarea", "label": "The step I did this week, and what I felt during it:"}, {"id": "f3", "type": "textarea", "label": "What my mind said afterward, and what I did with that:"}, {"id": "f4", "type": "textarea", "label": "A photo I am keeping, and what the moment in it was:"}]'::jsonb, array['body image', 'avoidance', 'exposure']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('upward-comparison-spotting-sheet', 'Upward Comparison Spotting Sheet', 'cbt'::resource_kind, 'A sheet for noticing that the client compares their appearance only to people they rank above themselves, never a fair sample.', 'Use it to help a client see the sampling bias in their appearance comparisons.', array['Adults', 'Teens']::text[], 'One week', 'For a week the client logs each appearance comparison and whom it was with. Then look at the list: who was chosen, who was left out, and who chose them. Nearly always the sample is upward and often edited or posed. The point is not to compare downward instead; it is to notice that the mind runs a rigged sample and to question its verdict. Pair with time away from the feeds that supply the sample.', '[{"id": "f0", "type": "textarea", "label": "Each comparison this week: who it was with, and where I saw them:"}, {"id": "f1", "type": "textarea", "label": "Who my mind chose to compare with, and who it skipped:"}, {"id": "f2", "type": "textarea", "label": "How many of the comparisons were with edited, posed or filtered images:"}, {"id": "f3", "type": "textarea", "label": "What a fair sample of people I actually see in a day would look like:"}, {"id": "f4", "type": "textarea", "label": "What this tells me about trusting my mind''s verdict on how I look:"}]'::jsonb, array['body image', 'thinking traps', 'core CBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('movement-for-joy-not-fixing-values-page', 'Movement for Joy Not Fixing Values Page', 'act'::resource_kind, 'A page for choosing movement because of what it gives the client, not to change how the body looks.', 'Use it to help a client reconnect with moving their body as a valued activity rather than a correction.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask what movement the client did as a child purely for fun: bikes, dancing, climbing, swimming. Then ask what movement has become since. Choose one kind of movement and define it by what it gives: fresh air, music, a friend, strength for carrying groceries. Nothing about appearance belongs on this page. Plan one session this week and rate it afterward only on joy and energy.', '[{"id": "f0", "type": "textarea", "label": "Movement I loved as a child, for its own sake:"}, {"id": "f1", "type": "textarea", "label": "What movement has turned into for me since:"}, {"id": "f2", "type": "textarea", "label": "A kind of movement I could choose for what it gives, and what that is:"}, {"id": "f3", "type": "textarea", "label": "The session I will do this week, and with whom if anyone:"}, {"id": "f4", "type": "textarea", "label": "Afterward: my joy and energy ratings, and nothing else:"}]'::jsonb, array['body image', 'values', 'committed action']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('participate-fully-at-the-pool-card', 'Participate Fully at the Pool Card', 'dbt'::resource_kind, 'A card for using the participate skill at a pool, beach or locker room: throwing oneself into the activity instead of monitoring the body.', 'Use it to help a client be fully in a water or changing-room setting they usually endure or avoid.', array['Adults', 'Teens']::text[], '20 minutes', 'Plan a real setting the client avoids or endures: a pool, a beach, a gym locker room. Teach participate: attention goes entirely into the swimming, the sand, the conversation, the cold water, and every time the body-monitoring commentary starts, the client names it and returns to the activity. Rate enjoyment afterward. No part of this card is about how the body looked; it is about how much of the afternoon the client got to have.', '[{"id": "f0", "type": "textarea", "label": "The setting I am going to, and when:"}, {"id": "f1", "type": "textarea", "label": "What I will throw myself into there (the swimming, the people, the sun):"}, {"id": "f2", "type": "textarea", "label": "What the monitoring commentary usually says, so I recognize it:"}, {"id": "f3", "type": "textarea", "label": "How I will return to the activity each time:"}, {"id": "f4", "type": "textarea", "label": "Afterward: how much of the time I was in the activity, and how it felt:"}]'::jsonb, array['body image', 'mindfulness', 'core DBT']::text[], '2026-11-11T15:00:00+00:00'::timestamptz),
  ('would-you-rather-body-neutral-edition', 'Would You Rather: Body Neutral Edition', 'game'::resource_kind, 'A would-you-rather game where every choice is about what bodies do and feel, never how they look, followed by a debrief.', 'Use it to get a group talking about bodies as something they live in, with laughter as the entry point.', array['Groups', 'Teens']::text[], '30 minutes', 'Prepare cards: would you rather have perfect balance or never get cold; be able to sleep anywhere or never get a stitch; hear your favorite song as if for the first time or taste your favorite food that way. Players vote, the minority explains, and a new card is drawn. No cards mention appearance, and the facilitator redirects if the group drifts there. Debrief what each player''s choices say about what they value in a body.', '[{"id": "f0", "type": "textarea", "label": "The card where I was in the minority, and why I chose it:"}, {"id": "f1", "type": "textarea", "label": "The card the group argued about most:"}, {"id": "f2", "type": "textarea", "label": "Something a body of mine does that I noticed I appreciate during the game:"}, {"id": "f3", "type": "textarea", "label": "What my choices seem to say about what I value in having a body:"}, {"id": "f4", "type": "textarea", "label": "A card I would add that is about doing or feeling, not looking:"}]'::jsonb, array['body image', 'game', 'body awareness']::text[], '2026-11-11T15:00:00+00:00'::timestamptz)
