-- Clinician library: 125 new resources for 2026-11-11 (five of every kind, five on every
-- topic), plus 50 resources dated 2026-10-27 that were in data/therapist-resources.json
-- but were still missing from the database. Each is an upsert on slug, so applying it twice is harmless.
-- Generated with: python3 tools/therapist_resources_sql.py <the 175 slugs>

on conflict (slug) do update set
  title      = excluded.title,
  kind       = excluded.kind,
  summary    = excluded.summary,
  goal       = excluded.goal,
  audience   = excluded.audience,
  duration   = excluded.duration,
  body_md    = excluded.body_md,
  fields     = excluded.fields,
  tags       = excluded.tags,
  created_at = excluded.created_at;
